window.__PAGE_RUNTIME_PARTIALS__["partials/guia-03-planificar-content.html"] = "\u003cbutton class=\"hamburger\" onclick=\"toggleSidebar()\" aria-label=\"Menú\"\u003e\u0026#9776;\u003c/button\u003e\r\n\u003cbutton class=\"btn-sb-expand\" onclick=\"showSidebar()\" title=\"Mostrar barra lateral\"\u003e\u0026#9776;\u003c/button\u003e\r\n\r\n\u003cdiv class=\"layout app-layout\"\u003e\r\n  \u003cnav class=\"sidebar\" id=\"sidebar\"\u003e\r\n    \u003cdiv class=\"sidebar-logo\"\u003e\r\n      \u003cdiv class=\"badge\"\u003eSENA · FPI\u003c/div\u003e\r\n      \u003ch2\u003eGuia 3 - Implementar componentes de las herramientas tecnológicas según procedimientos de la organización.\u003c/h2\u003e\r\n      \u003cp\u003eSistemas Teleinformaticos\u003c/p\u003e\r\n      \u003cbutton class=\"btn-sb-collapse\" onclick=\"hideSidebar()\" title=\"Ocultar barra lateral\"\u003e\u0026#9664;\u003c/button\u003e\r\n    \u003c/div\u003e\r\n\r\n    \u003cdiv class=\"sidebar-ficha\" id=\"sb-ficha-ok\" style=\"display:none\"\u003e\r\n      \u003cdiv class=\"sf-label\"\u003eTu grupo\u003c/div\u003e\r\n      \u003cdiv class=\"sf-inst\" id=\"sb-inst\"\u003e\u003c/div\u003e\r\n      \u003cdiv class=\"sf-meta\" id=\"sb-grupo-meta\"\u003e\u003c/div\u003e\r\n      \u003cdiv class=\"sf-badge\" id=\"sb-badge\"\u003e\u003c/div\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"sidebar-noficha\" id=\"sb-ficha-warn\"\u003e\r\n      \u003ca href=\"index.html\"\u003eInicio | Seleccionar grupo / ficha\u003c/a\u003e\r\n    \u003c/div\u003e\r\n\r\n    \u003cdiv class=\"progress-wrap\"\u003e\r\n      \u003cdiv class=\"progress-label\"\u003e\r\n        \u003cspan\u003eProgreso\u003c/span\u003e\r\n        \u003cspan id=\"progressValue\"\u003e0%\u003c/span\u003e\r\n      \u003c/div\u003e\r\n      \u003cdiv class=\"progress-bar-bg\"\u003e\r\n        \u003cdiv class=\"progress-bar\" id=\"progressBar\"\u003e\u003c/div\u003e\r\n      \u003c/div\u003e\r\n      \u003cp class=\"progress-note\"\u003eEl avance se guarda localmente en este navegador.\u003c/p\u003e\r\n      \u003cbutton type=\"button\" class=\"reset-button\" id=\"resetProgress\"\u003eReiniciar respuestas\u003c/button\u003e\r\n    \u003c/div\u003e\r\n\r\n    \u003cdiv class=\"nav-section\"\u003e\r\n      \u003cdiv class=\"nav-label\"\u003eInformaci\u0026oacute;n\u003c/div\u003e\r\n      \u003ca class=\"nav-link active\" href=\"#identificacion\" onclick=\"setActive(this)\"\u003e\r\n        \u003cspan class=\"icon\"\u003e\u0026#128203;\u003c/span\u003e Identificaci\u0026oacute;n\r\n      \u003c/a\u003e\r\n      \u003ca class=\"nav-link\" href=\"#presentacion\" onclick=\"setActive(this)\"\u003e\r\n        \u003cspan class=\"icon\"\u003e\u0026#128075;\u003c/span\u003e Presentaci\u0026oacute;n\r\n      \u003c/a\u003e\r\n    \u003c/div\u003e\r\n\r\n    \u003cdiv class=\"nav-section\"\u003e\r\n      \u003cdiv class=\"nav-label\"\u003eActividades\u003c/div\u003e\r\n      \u003ca class=\"nav-link\" href=\"#reflexion\" onclick=\"setActive(this)\"\u003e\r\n        \u003cspan class=\"icon\"\u003e\u0026#128172;\u003c/span\u003e 3.1 Reflexi\u0026oacute;n Inicial\r\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\r\n      \u003c/a\u003e\r\n      \u003ca class=\"nav-link\" href=\"#contexto\" onclick=\"setActive(this)\"\u003e\r\n        \u003cspan class=\"icon\"\u003e\u0026#128269;\u003c/span\u003e 3.2 Contextualizaci\u0026oacute;n\r\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\r\n      \u003c/a\u003e\r\n      \u003ca class=\"nav-link\" href=\"#apropiacion\" onclick=\"setActive(this)\"\u003e\r\n        \u003cspan class=\"icon\"\u003e\u0026#128218;\u003c/span\u003e 3.3 Apropiaci\u0026oacute;n\r\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\r\n      \u003c/a\u003e\r\n      \u003ca class=\"nav-link\" href=\"#transferencia\" onclick=\"setActive(this)\"\u003e\r\n        \u003cspan class=\"icon\"\u003e\u0026#128640;\u003c/span\u003e 3.4 Transferencia\r\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\r\n      \u003c/a\u003e\r\n    \u003c/div\u003e\r\n\r\n    \u003cdiv class=\"nav-section\"\u003e\r\n      \u003cdiv class=\"nav-label\"\u003eRecursos\u003c/div\u003e\r\n      \u003ca class=\"nav-link\" href=\"#evidencias\" onclick=\"setActive(this)\"\u003e\r\n        \u003cspan class=\"icon\"\u003e\u0026#128202;\u003c/span\u003e Evidencias\r\n      \u003c/a\u003e\r\n      \u003ca class=\"nav-link\" href=\"#glosario\" onclick=\"setActive(this)\"\u003e\r\n        \u003cspan class=\"icon\"\u003e\u0026#128214;\u003c/span\u003e Glosario\r\n      \u003c/a\u003e\r\n      \u003ca class=\"nav-link\" href=\"#referencias\" onclick=\"setActive(this)\"\u003e\r\n        \u003cspan class=\"icon\"\u003e\u0026#128279;\u003c/span\u003e Referencias\r\n      \u003c/a\u003e\r\n      \u003ca class=\"nav-link\" href=\"#material-apoyo\" onclick=\"setActive(this)\"\u003e\r\n        \u003cspan class=\"icon\"\u003e\u0026#128194;\u003c/span\u003e Material de Apoyo\r\n      \u003c/a\u003e\r\n      \u003ca class=\"nav-link\" href=\"#control-documento\" onclick=\"setActive(this)\"\u003e\r\n        \u003cspan class=\"icon\"\u003e\u0026#128221;\u003c/span\u003e Control del Documento\r\n      \u003c/a\u003e\r\n    \u003c/div\u003e\r\n\r\n    \u003cdiv class=\"nav-section\"\u003e\r\n      \u003cdiv class=\"nav-label\"\u003eGuia asignada\u003c/div\u003e\r\n      \u003ca class=\"nav-guide current\" id=\"currentGuideNavLink\" href=\"grupo-10a-guia-03-planificar-informacion.html\" data-current-file=\"grupo-10a-guia-03-planificar-informacion.html\"\u003e\r\n        \u003cspan class=\"g-icon\"\u003e\u0026#128215;\u003c/span\u003e\r\n        \u003cspan class=\"g-info\"\u003e\r\n          \u003cspan class=\"g-num\"\u003eGuia 3\u003c/span\u003e\r\n          \u003cspan class=\"g-name\" id=\"currentGuideNavLabel\"\u003eImplementar componentes | 10A\u003c/span\u003e\r\n        \u003c/span\u003e\r\n        \u003cspan class=\"g-tag actual\"\u003eActual\u003c/span\u003e\r\n      \u003c/a\u003e\r\n    \u003c/div\u003e\r\n\r\n    \u003ca class=\"nav-home-link\" href=\"calendario-academico-2026.html\"\u003e\u0026#128197; \u003cspan\u003eCalendario 2026\u003c/span\u003e\u003c/a\u003e\r\n    \u003ca class=\"nav-home-link\" href=\"index.html\"\u003e\u0026#127968; \u003cspan\u003eVolver al Inicio\u003c/span\u003e\u003c/a\u003e\r\n  \u003c/nav\u003e\r\n\r\n  \u003cdiv class=\"main app-main\"\u003e\r\n    \u003cdiv class=\"topbar\"\u003e\r\n      \u003cdiv class=\"topbar-title\"\u003e\r\n        \u003cstrong\u003eGuia 3 - Implementar componentes de las herramientas tecnológicas según procedimientos de la organización.\u003c/strong\u003e\r\n      \u003c/div\u003e\r\n      \u003cdiv class=\"topbar-meta\"\u003e\r\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#9201;\u003c/span\u003e\u003cspan\u003e56 horas\u003c/span\u003e\u003c/span\u003e\r\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#128197;\u003c/span\u003e\u003cspan\u003e2026\u003c/span\u003e\u003c/span\u003e\r\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#127979;\u003c/span\u003e\u003cspan id=\"topbarCampus\"\u003eJhon F. Kennedy | 10A\u003c/span\u003e\u003c/span\u003e\r\n      \u003c/div\u003e\r\n    \u003c/div\u003e\r\n\r\n    \u003cdiv class=\"content\"\u003e\r\n      \u003cdiv class=\"hero\" id=\"inicio\"\u003e\r\n        \u003cdiv class=\"tag\"\u003eGuia 3 | Fase: Planeacion\u003c/div\u003e\r\n        \u003ch1\u003eImplementar herramientas tecnologicas para una MiPyme\u003c/h1\u003e\r\n        \u003cp\u003e\r\n          En esta guia estudiarás, instalarás y verificarás herramientas tecnológicas\r\n          de uso real en soporte técnico, aplicarás un diagnóstico básico y elaborarás\r\n          un presupuesto de implementación para una MiPyme de Boyacá.\r\n        \u003c/p\u003e\r\n        \u003cdiv class=\"hero-meta\"\u003e\r\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127963; SENA \u0026mdash; Servicio Nacional de Aprendizaje\u003c/div\u003e\r\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#128205; Competencia: Operar herramientas informaticas y digitales\u003c/div\u003e\r\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#9201; 56 horas\u003c/div\u003e\r\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127891; C\u0026oacute;digo: 233108 \u0026middot; V1\u003c/div\u003e\r\n        \u003c/div\u003e\r\n      \u003c/div\u003e\r\n\r\n      \u003cdiv id=\"identificacion\" class=\"section-title\"\u003eIdentificaci\u0026oacute;n de la Gu\u0026iacute;a\u003c/div\u003e\r\n      \u003cdiv class=\"card open\"\u003e\r\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\r\n          \u003cdiv class=\"card-header-left\"\u003e\r\n            \u003cdiv class=\"card-icon\" style=\"background:#e8f5e9\"\u003e\u0026#128203;\u003c/div\u003e\r\n            \u003cdiv\u003e\r\n              \u003ch3\u003eDatos del Programa de Formaci\u0026oacute;n\u003c/h3\u003e\r\n              \u003cp\u003eInformaci\u0026oacute;n oficial del programa y la competencia\u003c/p\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n        \u003c/div\u003e\r\n        \u003cdiv class=\"card-body\"\u003e\r\n          \u003cdiv class=\"table-scroll\"\u003e\r\n            \u003ctable class=\"data-table ident-table\"\u003e\r\n              \u003ctbody\u003e\r\n                \u003ctr\u003e\u003ctd\u003eDenominaci\u0026oacute;n del Programa\u003c/td\u003e\u003ctd\u003eT\u0026eacute;cnico en Sistemas Teleinform\u0026aacute;ticos\u003c/td\u003e\u003c/tr\u003e\r\n                \u003ctr\u003e\u003ctd\u003eC\u0026oacute;digo del Programa\u003c/td\u003e\u003ctd\u003e233108 \u0026middot; V1.0\u003c/td\u003e\u003c/tr\u003e\r\n                \u003ctr\u003e\u003ctd\u003eNombre del Proyecto Formativo\u003c/td\u003e\u003ctd\u003eAlfabetizaci\u0026oacute;n Digital, Asesor\u0026iacute;a T\u0026eacute;cnica y Ciberseguridad para la Mejora de Actividades Productivas Locales en la zona de influencia del CIAS Puerto Boyac\u0026aacute;.\u003c/td\u003e\u003c/tr\u003e\r\n                \u003ctr\u003e\u003ctd\u003eFase del Proyecto\u003c/td\u003e\u003ctd\u003ePlaneaci\u0026oacute;n\u003c/td\u003e\u003c/tr\u003e\r\n                \u003ctr\u003e\u003ctd\u003eActividad del Proyecto\u003c/td\u003e\u003ctd\u003ePlanificar procesos de intervenci\u0026oacute;n en alfabetizaci\u0026oacute;n digital, asesor\u0026iacute;a t\u0026eacute;cnica y ciberseguridad.\u003c/td\u003e\u003c/tr\u003e\r\n                \u003ctr\u003e\u003ctd\u003eCompetencia\u003c/td\u003e\u003ctd\u003e220501121 - Operar herramientas inform\u0026aacute;ticas y digitales de acuerdo con protocolos y manuales t\u0026eacute;cnicos.\u003c/td\u003e\u003c/tr\u003e\r\n                \u003ctr\u003e\u003ctd\u003eResultado de Aprendizaje\u003c/td\u003e\u003ctd\u003eRAP 02 Implementar componentes de las herramientas tecnol\u0026oacute;gicas seg\u0026uacute;n procedimientos de la organizaci\u0026oacute;n.\u003c/td\u003e\u003c/tr\u003e\r\n                \u003ctr\u003e\u003ctd\u003eDuraci\u0026oacute;n\u003c/td\u003e\u003ctd\u003e56 Horas\u003c/td\u003e\u003c/tr\u003e\r\n              \u003c/tbody\u003e\r\n            \u003c/table\u003e\r\n          \u003c/div\u003e\r\n        \u003c/div\u003e\r\n      \u003c/div\u003e\r\n\r\n      \u003cdiv id=\"presentacion\" class=\"section-title\"\u003ePresentaci\u0026oacute;n\u003c/div\u003e\r\n      \u003cdiv class=\"card open\"\u003e\r\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\r\n          \u003cdiv class=\"card-header-left\"\u003e\r\n            \u003cdiv class=\"card-icon\" style=\"background:#e3f2fd\"\u003e\u0026#128075;\u003c/div\u003e\r\n            \u003cdiv\u003e\r\n              \u003ch3\u003eBienvenida a la Gu\u0026iacute;a\u003c/h3\u003e\r\n              \u003cp\u003eConoce el contexto, el alcance y las metas de este recorrido formativo\u003c/p\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n        \u003c/div\u003e\r\n        \u003cdiv class=\"card-body\"\u003e\r\n          \u003cp class=\"intro-text\"\u003e\u003cstrong\u003e\u0026iexcl;Bienvenido, aprendiz!\u003c/strong\u003e\u003c/p\u003e\r\n          \u003cp class=\"intro-text\"\u003e\r\n            En el mundo actual, las organizaciones dependen de la tecnolog\u0026iacute;a para operar.\r\n            Las herramientas inform\u0026aacute;ticas \u0026mdash;desde aplicaciones ofim\u0026aacute;ticas hasta\r\n            plataformas de gesti\u0026oacute;n\u0026mdash; son la base del trabajo diario. Saber instalarlas,\r\n            configurarlas correctamente y documentar cada procedimiento no es solo una habilidad\r\n            t\u0026eacute;cnica: es una competencia profesional que te distinguir\u0026aacute; en el mercado\r\n            laboral.\r\n          \u003c/p\u003e\r\n          \u003cp class=\"intro-text\"\u003e\r\n            En esta gu\u0026iacute;a desarrollar\u0026aacute;s la competencia central del RAP 02:\r\n            implementar herramientas tecnol\u0026oacute;gicas en equipos reales de peque\u0026ntilde;as\r\n            empresas, siguiendo manuales t\u0026eacute;cnicos y procedimientos organizacionales. Esto\r\n            implica:\r\n          \u003c/p\u003e\r\n          \u003cul class=\"intro-text\" style=\"padding-left:1.2rem;margin:0 0 12px;line-height:1.7\"\u003e\r\n            \u003cli\u003e\r\n              \u003cstrong\u003eImplementar herramientas tecnol\u0026oacute;gicas:\u003c/strong\u003e aprender\u0026aacute;s a\r\n              instalar y configurar software, herramientas de diagn\u0026oacute;stico y recursos\r\n              digitales para el soporte t\u0026eacute;cnico en infraestructuras tecnol\u0026oacute;gicas,\r\n              siguiendo manuales y procedimientos organizacionales (RAP 02).\r\n            \u003c/li\u003e\r\n          \u003c/ul\u003e\r\n          \u003cp class=\"intro-text\"\u003e\r\n            Esta gu\u0026iacute;a est\u0026aacute; articulada con el Proyecto Formativo\r\n            \u003cem\u003e\u0026ldquo;Alfabetizaci\u0026oacute;n Digital, Asesor\u0026iacute;a T\u0026eacute;cnica y\r\n            Ciberseguridad para la Mejora de Actividades Productivas Locales en la zona de\r\n            influencia del CIAS Puerto Boyac\u0026aacute;\u0026rdquo;\u003c/em\u003e. Piensa en esta situaci\u0026oacute;n\r\n            concreta: el due\u0026ntilde;o de un negocio en Puerto Boyac\u0026aacute; te pide que dejes\r\n            listos tres computadores nuevos en dos d\u0026iacute;as. \u0026iquest;Por d\u0026oacute;nde empiezas?\r\n            \u0026iquest;Qu\u0026eacute; instalas primero y por qu\u0026eacute;? \u0026iquest;C\u0026oacute;mo verificas\r\n            que todo funciona antes de entregar? Esta gu\u0026iacute;a te entrena para responder esas\r\n            preguntas con m\u0026eacute;todo y responsabilidad profesional.\r\n          \u003c/p\u003e\r\n          \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\r\n            \u003cdiv class=\"label\"\u003e\u0026#128204; Nota\u003c/div\u003e\r\n            \u003cp\u003e\r\n              Antes de comenzar cada actividad: lee las instrucciones completas, ten los\r\n              materiales listos y guarda tus evidencias con nombres descriptivos en una carpeta\r\n              organizada. No saltes pasos. Las evidencias que generes formar\u0026aacute;n parte de tu\r\n              portafolio de aprendizaje y ser\u0026aacute;n evaluadas con criterios t\u0026eacute;cnicos\r\n              precisos, tal como ocurrir\u0026aacute; en tu vida profesional.\r\n            \u003c/p\u003e\r\n          \u003c/div\u003e\r\n        \u003c/div\u003e\r\n      \u003c/div\u003e\r\n\r\n      \u003cdiv id=\"reflexion\" class=\"section-title\"\u003e3.1 \u0026middot; Actividades de Reflexi\u0026oacute;n Inicial\u003c/div\u003e\r\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\r\n        \u003cp\u003eEstas actividades se desarrollan al inicio de cada sesion de 8 horas. Buscan activar tu pensamiento, conectar tu experiencia previa con la nueva competencia y prepararte para el trabajo tecnico del dia.\u003c/p\u003e\r\n      \u003c/div\u003e\r\n      \u003cdiv class=\"card open cat-reflexion\"\u003e\r\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\r\n          \u003cdiv class=\"card-header-left\"\u003e\r\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128172;\u003c/div\u003e\r\n            \u003cdiv\u003e\r\n              \u003ch3\u003eActividades de Reflexi\u0026oacute;n Inicial\u003c/h3\u003e\r\n              \u003cp\u003e2 actividades \u0026middot; Duraci\u0026oacute;n aproximada: 1 hora\u003c/p\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n        \u003c/div\u003e\r\n        \u003cdiv class=\"card-body\"\u003e\r\n          \u003cdiv class=\"activity open mission-card\"\u003e\r\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\r\n              \u003cspan class=\"activity-num\"\u003e3.1.1\u003c/span\u003e\r\n              \u003cspan class=\"activity-title\"\u003e\u0026#128214; Estudio de caso: La empresa sin herramientas adecuadas\u003c/span\u003e\r\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n            \u003c/div\u003e\r\n            \u003cdiv class=\"activity-body\"\u003e\r\n              \u003cp class=\"intro-text\"\u003e\r\n                Antes de instalar cualquier herramienta o documentar cualquier proceso, es\r\n                necesario comprender el contexto real en el que se aplican estas competencias.\r\n                Esta actividad busca activar tus conocimientos previos y conectarlos con\r\n                situaciones del mundo laboral.\r\n              \u003c/p\u003e\r\n\r\n              \u003carticle class=\"story-card\"\u003e\r\n                \u003ch3\u003e\u0026#128214; Escenario\u003c/h3\u003e\r\n                \u003cp\u003e\r\n                  La empresa \u003cstrong\u003e\u0026ldquo;TechBoyC\u0026aacute; S.A.S.\u0026rdquo;\u003c/strong\u003e acaba de\r\n                  adquirir 20 equipos de c\u0026oacute;mputo nuevos para su \u0026aacute;rea\r\n                  administrativa. El gerente le ha pedido al t\u0026eacute;cnico de sistemas que los\r\n                  dejes listos para trabajar. Al revisar, el t\u0026eacute;cnico descubre que los\r\n                  equipos no tienen suite ofim\u0026aacute;tica instalada, que el antivirus\r\n                  est\u0026aacute; desactualizado, que no existe ning\u0026uacute;n registro de los\r\n                  procedimientos t\u0026eacute;cnicos anteriores y que tampoco hay un inventario de\r\n                  los activos de software. El t\u0026eacute;cnico debe resolver la situaci\u0026oacute;n\r\n                  en dos d\u0026iacute;as h\u0026aacute;biles.\r\n                \u003c/p\u003e\r\n              \u003c/article\u003e\r\n\r\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px;\"\u003e\r\n                \u003ch3\u003eResponde individualmente en tu bit\u0026aacute;cora de aprendizaje:\u003c/h3\u003e\r\n                \u003clabel\u003e\r\n                  \u003cspan\u003e1. \u0026iquest;Qu\u0026eacute; herramientas inform\u0026aacute;ticas necesitar\u0026iacute;a instalar el t\u0026eacute;cnico para que los equipos est\u0026eacute;n operativos? Justifica tu respuesta.\u003c/span\u003e\r\n                  \u003ctextarea rows=\"5\" data-store=\"reflexion_herramientas\" data-track\u003e\u003c/textarea\u003e\r\n                \u003c/label\u003e\r\n                \u003clabel\u003e\r\n                  \u003cspan\u003e2. \u0026iquest;Qu\u0026eacute; informaci\u0026oacute;n deber\u0026iacute;a registrar el t\u0026eacute;cnico en una ficha t\u0026eacute;cnica o formato de inventario? \u0026iquest;Para qu\u0026eacute; sirve ese registro?\u003c/span\u003e\r\n                  \u003ctextarea rows=\"4\" data-store=\"reflexion_registro\" data-track\u003e\u003c/textarea\u003e\r\n                \u003c/label\u003e\r\n                \u003clabel\u003e\r\n                  \u003cspan\u003e3. \u0026iquest;Qu\u0026eacute; consecuencias tiene para una empresa no tener documentados sus procesos tecnol\u0026oacute;gicos?\u003c/span\u003e\r\n                  \u003ctextarea rows=\"4\" data-store=\"reflexion_consecuencias\" data-track\u003e\u003c/textarea\u003e\r\n                \u003c/label\u003e\r\n                \u003clabel\u003e\r\n                  \u003cspan\u003e4. \u0026iquest;Has vivido una situaci\u0026oacute;n parecida (en casa, el colegio o una empresa)? Descr\u0026iacute;bela brevemente.\u003c/span\u003e\r\n                  \u003ctextarea rows=\"3\" data-store=\"reflexion_experiencia\" data-track\u003e\u003c/textarea\u003e\r\n                \u003c/label\u003e\r\n                \u003cdiv id=\"bitacora311DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\r\n                \u003cdiv class=\"act-btn-group\"\u003e\r\n                  \u003cbutton type=\"button\" id=\"btnGuardarBitacora\"\r\n                    onclick=\"guardarBitacora311()\"\r\n                    class=\"btn-save-response\"\u003e\r\n                    \u0026#128190; Guardar respuestas\r\n                  \u003c/button\u003e\r\n                  \u003cbutton class=\"btn-export-word\" type=\"button\" onclick=\"openBitacoraExportModal()\"\u003e\r\n                    \u0026#128196; Exportar bit\u0026aacute;cora a Word\r\n                  \u003c/button\u003e\r\n                \u003c/div\u003e\r\n                \u003cdiv id=\"bitacoraStatus311\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\r\n                  \u0026#9989; Respuestas guardadas correctamente.\r\n                \u003c/div\u003e\r\n              \u003c/article\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n\r\n          \u003cdiv class=\"activity mission-card\"\u003e\r\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\r\n              \u003cspan class=\"activity-num\"\u003e3.1.2\u003c/span\u003e\r\n              \u003cspan class=\"activity-title\"\u003e\u0026#127908; Socializaci\u0026oacute;n en grupo\u003c/span\u003e\r\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n            \u003c/div\u003e\r\n            \u003cdiv class=\"activity-body\"\u003e\r\n              \u003cp class=\"intro-text\"\u003e\r\n                En grupos de tres (3) aprendices, socialicen sus respuestas y preparen una\r\n                conclusi\u0026oacute;n grupal de m\u0026aacute;ximo 5 minutos para presentar al grupo.\r\n                Enfoquen la discusi\u0026oacute;n en: \u003cstrong\u003e\u0026iquest;Por qu\u0026eacute; es clave que el\r\n                t\u0026eacute;cnico instale las herramientas correctas antes de entregar un equipo a\r\n                una empresa?\u003c/strong\u003e\r\n              \u003c/p\u003e\r\n\r\n              \u003cdiv id=\"equipoGuia3Mount_socializacion312\" class=\"equipo-guia3-block\" data-equipo-activity=\"socializacion312\" style=\"margin:14px 0;padding:14px 16px;border:1px solid #cfe0d3;border-left:5px solid #0b6b35;border-radius:10px;background:linear-gradient(180deg,#f1f9f3,#ffffff)\"\u003e\r\n                \u003cdiv style=\"display:flex;align-items:center;gap:8px;margin-bottom:6px;font-weight:700;color:#0b6b35;font-size:.92rem\"\u003e\r\n                  \u003cspan aria-hidden=\"true\"\u003e\u0026#128101;\u003c/span\u003e Equipo de trabajo de esta actividad\r\n                \u003c/div\u003e\r\n                \u003cp class=\"intro-text\" style=\"margin:0 0 10px;font-size:.84rem;color:#455a64;line-height:1.55\"\u003e\r\n                  Esta actividad se trabaja en equipo de \u003cstrong\u003e3 aprendices\u003c/strong\u003e. Configura aqu\u0026iacute; tu equipo para 3.1.2; puede ser diferente al de las actividades 3.2.1 y 3.2.2.\r\n                \u003c/p\u003e\r\n                \u003cdiv id=\"equipoGuia3Summary_socializacion312\"\u003e\u003c/div\u003e\r\n                \u003cdiv id=\"equipoGuia3Config_socializacion312\" style=\"display:none\"\u003e\r\n                  \u003cdiv style=\"margin:6px 0 6px;font-weight:600;font-size:.86rem;color:#1b5e20\"\u003eSelecciona a tus 2 compa\u0026ntilde;eros (tu nombre ya est\u0026aacute; incluido):\u003c/div\u003e\r\n                  \u003cdiv id=\"equipoGuia3RosterMount_socializacion312\" style=\"display:flex;flex-direction:column;gap:6px;max-height:240px;overflow:auto;padding:8px 10px;border:1px solid #cfe0d3;border-radius:8px;background:#ffffff\"\u003e\u003c/div\u003e\r\n                  \u003cdiv id=\"equipoGuia3FormHint_socializacion312\" class=\"intro-text\" style=\"margin:8px 0 0;font-size:.82rem;color:#4b5563\"\u003eCargando roster de la ficha\u0026hellip;\u003c/div\u003e\r\n                  \u003cdiv class=\"act-btn-group\" style=\"margin-top:10px;display:flex;gap:8px;flex-wrap:wrap\"\u003e\r\n                    \u003cbutton type=\"button\" onclick=\"confirmarEquipoGuia3('socializacion312')\" class=\"btn-save-response\"\u003e\u0026#128101; Confirmar equipo\u003c/button\u003e\r\n                    \u003cbutton type=\"button\" onclick=\"cancelarEquipoGuia3Config('socializacion312')\" style=\"padding:8px 16px;border:1px solid #cfe0d3;background:#ffffff;color:#37474f;border-radius:6px;font-family:inherit;font-size:.88rem;cursor:pointer\"\u003eCancelar\u003c/button\u003e\r\n                  \u003c/div\u003e\r\n                \u003c/div\u003e\r\n              \u003c/div\u003e\r\n\r\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px;\"\u003e\r\n                \u003ch3\u003eConclusi\u0026oacute;n grupal\u003c/h3\u003e\r\n                \u003clabel\u003e\r\n                  \u003cspan\u003eResumen de la conclusi\u0026oacute;n del equipo (m\u0026aacute;ximo 5 minutos al exponerla)\u003c/span\u003e\r\n                  \u003ctextarea rows=\"6\" data-store=\"socializacion_conclusion\" data-track\u003e\u003c/textarea\u003e\r\n                \u003c/label\u003e\r\n                \u003clabel\u003e\r\n                  \u003cspan\u003eIdea central que sustentar\u0026aacute;n en la plenaria\u003c/span\u003e\r\n                  \u003ctextarea rows=\"3\" data-store=\"socializacion_pregunta_central\" data-track\u003e\u003c/textarea\u003e\r\n                \u003c/label\u003e\r\n                \u003cdiv id=\"socializacion312DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\r\n                \u003cdiv class=\"act-btn-group\"\u003e\r\n                  \u003cbutton type=\"button\" id=\"btnGuardarSocializacion\"\r\n                    onclick=\"guardarSocializacion312()\"\r\n                    class=\"btn-save-response\"\u003e\r\n                    \u0026#128190; Guardar respuestas\r\n                  \u003c/button\u003e\r\n                \u003c/div\u003e\r\n                \u003cdiv id=\"socializacionStatus312\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\r\n                  \u0026#9989; Respuestas guardadas correctamente.\r\n                \u003c/div\u003e\r\n              \u003c/article\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n        \u003c/div\u003e\r\n      \u003c/div\u003e\r\n\r\n      \u003cdiv id=\"contexto\" class=\"section-title\"\u003e3.2 \u0026middot; Actividades de Contextualizaci\u0026oacute;n e Identificaci\u0026oacute;n de Conocimientos\u003c/div\u003e\r\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\r\n        \u003cp\u003e\r\n          En esta actividad construir\u0026aacute;s la base conceptual necesaria para implementar y\r\n          documentar herramientas tecnol\u0026oacute;gicas. Estudia los temas propuestos, investiga\r\n          en las fuentes sugeridas y construye un mapa conceptual que demuestre tu\r\n          comprensi\u0026oacute;n.\r\n        \u003c/p\u003e\r\n        \u003cp style=\"margin-top:6px\"\u003e\u003cstrong\u003eDuraci\u0026oacute;n:\u003c/strong\u003e 8 horas de trabajo directo + 4 horas aut\u0026oacute;nomas.\u003c/p\u003e\r\n      \u003c/div\u003e\r\n      \u003cdiv class=\"card open cat-contexto\"\u003e\r\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\r\n          \u003cdiv class=\"card-header-left\"\u003e\r\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128269;\u003c/div\u003e\r\n            \u003cdiv\u003e\r\n              \u003ch3\u003eActividades de Contextualizaci\u0026oacute;n\u003c/h3\u003e\r\n              \u003cp\u003e2 actividades \u0026middot; Duraci\u0026oacute;n: 8 horas directas + 4 aut\u0026oacute;nomas\u003c/p\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n        \u003c/div\u003e\r\n        \u003cdiv class=\"card-body\"\u003e\r\n          \u003cdiv class=\"activity open mission-card\"\u003e\r\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\r\n              \u003cspan class=\"activity-num\"\u003e3.2.1\u003c/span\u003e\r\n              \u003cspan class=\"activity-title\"\u003e\u0026#128218; Estudio de contenidos tem\u0026aacute;ticos\u003c/span\u003e\r\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n            \u003c/div\u003e\r\n            \u003cdiv class=\"activity-body\"\u003e\r\n              \u003cp class=\"intro-text\"\u003e\r\n                Estudia los temas del Bloque A. El instructor te asignar\u0026aacute; los recursos de\r\n                consulta. Toma notas organizadas y prep\u0026aacute;rate para explicar lo aprendido a\r\n                tu grupo.\r\n              \u003c/p\u003e\r\n\r\n              \u003cdiv id=\"equipoGuia3Mount_tabla321\" class=\"equipo-guia3-block\" data-equipo-activity=\"tabla321\" style=\"margin:14px 0;padding:14px 16px;border:1px solid #cfe0d3;border-left:5px solid #0b6b35;border-radius:10px;background:linear-gradient(180deg,#f1f9f3,#ffffff)\"\u003e\r\n                \u003cdiv style=\"display:flex;align-items:center;gap:8px;margin-bottom:6px;font-weight:700;color:#0b6b35;font-size:.92rem\"\u003e\r\n                  \u003cspan aria-hidden=\"true\"\u003e\u0026#128101;\u003c/span\u003e Equipo de trabajo de esta actividad\r\n                \u003c/div\u003e\r\n                \u003cp class=\"intro-text\" style=\"margin:0 0 10px;font-size:.84rem;color:#455a64;line-height:1.55\"\u003e\r\n                  Esta actividad se trabaja en equipo de \u003cstrong\u003e3 aprendices\u003c/strong\u003e. Configura aqu\u0026iacute; tu equipo para 3.2.1; puede ser diferente al de las actividades 3.1.2 y 3.2.2.\r\n                \u003c/p\u003e\r\n                \u003cdiv id=\"equipoGuia3Summary_tabla321\"\u003e\u003c/div\u003e\r\n                \u003cdiv id=\"equipoGuia3Config_tabla321\" style=\"display:none\"\u003e\r\n                  \u003cdiv style=\"margin:6px 0 6px;font-weight:600;font-size:.86rem;color:#1b5e20\"\u003eSelecciona a tus 2 compa\u0026ntilde;eros (tu nombre ya est\u0026aacute; incluido):\u003c/div\u003e\r\n                  \u003cdiv id=\"equipoGuia3RosterMount_tabla321\" style=\"display:flex;flex-direction:column;gap:6px;max-height:240px;overflow:auto;padding:8px 10px;border:1px solid #cfe0d3;border-radius:8px;background:#ffffff\"\u003e\u003c/div\u003e\r\n                  \u003cdiv id=\"equipoGuia3FormHint_tabla321\" class=\"intro-text\" style=\"margin:8px 0 0;font-size:.82rem;color:#4b5563\"\u003eCargando roster de la ficha\u0026hellip;\u003c/div\u003e\r\n                  \u003cdiv class=\"act-btn-group\" style=\"margin-top:10px;display:flex;gap:8px;flex-wrap:wrap\"\u003e\r\n                    \u003cbutton type=\"button\" onclick=\"confirmarEquipoGuia3('tabla321')\" class=\"btn-save-response\"\u003e\u0026#128101; Confirmar equipo\u003c/button\u003e\r\n                    \u003cbutton type=\"button\" onclick=\"cancelarEquipoGuia3Config('tabla321')\" style=\"padding:8px 16px;border:1px solid #cfe0d3;background:#ffffff;color:#37474f;border-radius:6px;font-family:inherit;font-size:.88rem;cursor:pointer\"\u003eCancelar\u003c/button\u003e\r\n                  \u003c/div\u003e\r\n                \u003c/div\u003e\r\n              \u003c/div\u003e\r\n\r\n              \u003carticle class=\"support-card\"\u003e\r\n                \u003ch3\u003eInstrucciones para el estudio\u003c/h3\u003e\r\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.75\"\u003e\r\n                  \u003cli\u003eForma un equipo de 3 aprendices. Distribuyan los temas entre los integrantes (2 o 3 temas por persona).\u003c/li\u003e\r\n                  \u003cli\u003eEstudia los temas asignados usando los recursos indicados. Tiempo de estudio aut\u0026oacute;nomo: 2 horas.\u003c/li\u003e\r\n                  \u003cli\u003eEn la sesi\u0026oacute;n, cada integrante explica sus temas al equipo (5 minutos por tema). Completa tus apuntes.\u003c/li\u003e\r\n                  \u003cli\u003eComo equipo, elaboren una tabla resumen en LibreOffice Calc con columnas: \u0026ldquo;Herramienta o proceso\u0026rdquo;, \u0026ldquo;Para qu\u0026eacute; sirve\u0026rdquo;, \u0026ldquo;Aplicaci\u0026oacute;n en una empresa local\u0026rdquo;.\u003c/li\u003e\r\n                  \u003cli\u003eExporta la tabla a PDF (Archivo \u0026rarr; Exportar como PDF). Nombre: \u003ccode\u003eBloqueA_Resumen_[TuNombre]_v1.0.pdf\u003c/code\u003e.\u003c/li\u003e\r\n                \u003c/ol\u003e\r\n              \u003c/article\u003e\r\n\r\n              \u003cdiv style=\"background:#1b5e20;color:#fff;border-radius:6px 6px 0 0;padding:8px 14px;font-size:0.8rem;font-weight:700;letter-spacing:.04em;margin-top:16px\"\u003e\r\n                BLOQUE A \u0026mdash; Herramientas Tecnol\u0026oacute;gicas (RAP 02)\r\n              \u003c/div\u003e\r\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:0;border-radius:0 0 8px 8px;overflow:hidden;border:1px solid #c8e6c9;border-top:none\"\u003e\r\n                \u003ctable class=\"data-table\" style=\"margin:0\"\u003e\r\n                  \u003ctbody\u003e\r\n                    \u003ctr\u003e\u003ctd\u003eManual t\u0026eacute;cnico: funci\u0026oacute;n, estructura y uso.\u003c/td\u003e\u003c/tr\u003e\r\n                    \u003ctr\u003e\u003ctd\u003eProcedimiento de instalaci\u0026oacute;n de software y herramientas ofim\u0026aacute;ticas.\u003c/td\u003e\u003c/tr\u003e\r\n                    \u003ctr\u003e\u003ctd\u003ePar\u0026aacute;metros de licenciamiento y almacenamiento.\u003c/td\u003e\u003c/tr\u003e\r\n                    \u003ctr\u003e\u003ctd\u003eHerramientas de diagn\u0026oacute;stico para soporte t\u0026eacute;cnico.\u003c/td\u003e\u003c/tr\u003e\r\n                    \u003ctr\u003e\u003ctd\u003eMotores de b\u0026uacute;squeda t\u0026eacute;cnica: uso eficiente.\u003c/td\u003e\u003c/tr\u003e\r\n                    \u003ctr\u003e\u003ctd\u003ePlataformas de gesti\u0026oacute;n: Google Workspace, Microsoft 365, Teams.\u003c/td\u003e\u003c/tr\u003e\r\n                    \u003ctr\u003e\u003ctd\u003eCompatibilidad de herramientas y resoluci\u0026oacute;n de problemas b\u0026aacute;sicos.\u003c/td\u003e\u003c/tr\u003e\r\n                    \u003ctr\u003e\u003ctd\u003eGesti\u0026oacute;n de cuentas de acceso corporativas.\u003c/td\u003e\u003c/tr\u003e\r\n                  \u003c/tbody\u003e\r\n                \u003c/table\u003e\r\n              \u003c/div\u003e\r\n\r\n              \u003cdiv style=\"background:#0d47a1;color:#fff;border-radius:6px 6px 0 0;padding:8px 14px;font-size:0.8rem;font-weight:700;letter-spacing:.04em;margin-top:14px\"\u003e\r\n                BLOQUE B \u0026mdash; Documentaci\u0026oacute;n T\u0026eacute;cnica\r\n              \u003c/div\u003e\r\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:0;border-radius:0 0 8px 8px;overflow:hidden;border:1px solid #bbdefb;border-top:none\"\u003e\r\n                \u003ctable class=\"data-table\" style=\"margin:0\"\u003e\r\n                  \u003ctbody\u003e\r\n                    \u003ctr\u003e\u003ctd\u003eDocumentaci\u0026oacute;n t\u0026eacute;cnica: fichas t\u0026eacute;cnicas, hojas de vida de equipos.\u003c/td\u003e\u003c/tr\u003e\r\n                    \u003ctr\u003e\u003ctd\u003eInventario de activos de software y hardware.\u003c/td\u003e\u003c/tr\u003e\r\n                    \u003ctr\u003e\u003ctd\u003eFormatos y plantillas de registro t\u0026eacute;cnico.\u003c/td\u003e\u003c/tr\u003e\r\n                    \u003ctr\u003e\u003ctd\u003eListas de chequeo (checklist): elaboraci\u0026oacute;n y uso.\u003c/td\u003e\u003c/tr\u003e\r\n                    \u003ctr\u003e\u003ctd\u003eConvenci\u0026oacute;n de nombres y versionado de archivos.\u003c/td\u003e\u003c/tr\u003e\r\n                    \u003ctr\u003e\u003ctd\u003eTipos documentales en tecnolog\u0026iacute;a.\u003c/td\u003e\u003c/tr\u003e\r\n                    \u003ctr\u003e\u003ctd\u003eGesti\u0026oacute;n de la informaci\u0026oacute;n: protecci\u0026oacute;n, organizaci\u0026oacute;n y respaldo.\u003c/td\u003e\u003c/tr\u003e\r\n                    \u003ctr\u003e\u003ctd\u003eBuenas pr\u0026aacute;cticas de documentaci\u0026oacute;n seg\u0026uacute;n manuales.\u003c/td\u003e\u003c/tr\u003e\r\n                  \u003c/tbody\u003e\r\n                \u003c/table\u003e\r\n              \u003c/div\u003e\r\n\r\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\r\n                \u003cdiv class=\"label\"\u003e\u0026#128204; Nota\u003c/div\u003e\r\n                \u003cp\u003e\r\n                  Recurso recomendado: Material de formaci\u0026oacute;n IT Essentials de Cisco\r\n                  (M\u0026oacute;dulos de Herramientas de Soporte y Documentaci\u0026oacute;n). Disponible\r\n                  en Cisco Networking Academy:\r\n                  \u003ca href=\"https://www.netacad.com\" target=\"_blank\" rel=\"noopener\"\u003ehttps://www.netacad.com\u003c/a\u003e.\r\n                \u003c/p\u003e\r\n              \u003c/div\u003e\r\n\r\n              \u003carticle class=\"notes-card\" style=\"margin-top:18px\"\u003e\r\n                \u003ch3\u003e\u0026#128203; Tabla resumen del bloque tem\u0026aacute;tico (trabajo en equipo)\u003c/h3\u003e\r\n                \u003cp class=\"intro-text\" style=\"margin:0 0 10px;font-size:.88rem;color:#455a64;line-height:1.55\"\u003e\r\n                  Completa la tabla resumen aqu\u0026iacute; mismo. Las filas vienen pre-cargadas con los 16 temas\r\n                  de los Bloques A y B; pueden editarlas, ajustarlas o sustituirlas seg\u0026uacute;n el reparto de\r\n                  temas del equipo. Para cada fila escriban \u0026laquo;Para qu\u0026eacute; sirve\u0026raquo; y una\r\n                  \u0026laquo;Aplicaci\u0026oacute;n en una empresa local\u0026raquo; concreta. Cuando terminen, presionen\r\n                  \u003cstrong\u003eGuardar tabla\u003c/strong\u003e; podr\u0026aacute;n exportarla a Word con el encabezado institucional.\r\n                \u003c/p\u003e\r\n                \u003cdiv class=\"table-scroll\" style=\"border-radius:8px;overflow:hidden;border:1px solid #c8e6c9\"\u003e\r\n                  \u003ctable class=\"data-table\" style=\"margin:0\"\u003e\r\n                    \u003cthead\u003e\r\n                      \u003ctr\u003e\r\n                        \u003cth style=\"width:30%;background:#1b5e20;color:#fff\"\u003eHerramienta o proceso\u003c/th\u003e\r\n                        \u003cth style=\"background:#1b5e20;color:#fff\"\u003e\u0026iquest;Para qu\u0026eacute; sirve?\u003c/th\u003e\r\n                        \u003cth style=\"background:#1b5e20;color:#fff\"\u003eAplicaci\u0026oacute;n en una empresa local\u003c/th\u003e\r\n                      \u003c/tr\u003e\r\n                    \u003c/thead\u003e\r\n                    \u003ctbody id=\"tabla321Body\"\u003e\u003c/tbody\u003e\r\n                  \u003c/table\u003e\r\n                \u003c/div\u003e\r\n                \u003cp class=\"intro-text\" style=\"margin:10px 0 0;font-size:.82rem;color:#6b7280\"\u003e\r\n                  \u0026#128161; Sugerencia: piensen en empresas reales de Puerto Boyac\u0026aacute; o de su entorno\r\n                  (ferreter\u0026iacute;a, droguer\u0026iacute;a, taller, granja, restaurante, papeler\u0026iacute;a, etc.)\r\n                  para que la columna de aplicaci\u0026oacute;n sea concreta y real.\r\n                \u003c/p\u003e\r\n                \u003cdiv id=\"tabla321DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\r\n                \u003cdiv class=\"act-btn-group\"\u003e\r\n                  \u003cbutton type=\"button\" id=\"btnGuardarTabla321\"\r\n                    onclick=\"guardarTabla321()\"\r\n                    class=\"btn-save-response\"\u003e\r\n                    \u0026#128190; Guardar tabla\r\n                  \u003c/button\u003e\r\n                  \u003cbutton class=\"btn-export-word\" type=\"button\" onclick=\"exportarTabla321Word()\"\u003e\r\n                    \u0026#128196; Exportar tabla a Word\r\n                  \u003c/button\u003e\r\n                \u003c/div\u003e\r\n                \u003cdiv id=\"tabla321Status\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\r\n                  \u0026#9989; Tabla guardada correctamente.\r\n                \u003c/div\u003e\r\n              \u003c/article\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n\r\n          \u003cdiv class=\"activity mission-card\"\u003e\r\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\r\n              \u003cspan class=\"activity-num\"\u003e3.2.2\u003c/span\u003e\r\n              \u003cspan class=\"activity-title\"\u003e\u0026#128506;\u0026#65039; Construcci\u0026oacute;n del mapa conceptual\u003c/span\u003e\r\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n            \u003c/div\u003e\r\n            \u003cdiv class=\"activity-body\"\u003e\r\n              \u003cp class=\"intro-text\"\u003e\r\n                En equipos de tres (3) aprendices, van a elaborar \u003cstrong\u003eun solo mapa conceptual\u003c/strong\u003e\r\n                que muestre c\u0026oacute;mo se relacionan las \u003cem\u003eherramientas tecnol\u0026oacute;gicas\u003c/em\u003e con\r\n                su \u003cem\u003edocumentaci\u0026oacute;n t\u0026eacute;cnica\u003c/em\u003e dentro de la gesti\u0026oacute;n de\r\n                informaci\u0026oacute;n de una empresa. \u003cstrong\u003eNo se trata de dibujar de una sola vez\u003c/strong\u003e:\r\n                primero van a planear el mapa aqu\u0026iacute; abajo paso a paso, y solo despu\u0026eacute;s lo van\r\n                a dibujar.\r\n              \u003c/p\u003e\r\n\r\n              \u003cdiv id=\"equipoGuia3Mount_mapa322\" class=\"equipo-guia3-block\" data-equipo-activity=\"mapa322\" style=\"margin:14px 0;padding:14px 16px;border:1px solid #cfe0d3;border-left:5px solid #0b6b35;border-radius:10px;background:linear-gradient(180deg,#f1f9f3,#ffffff)\"\u003e\r\n                \u003cdiv style=\"display:flex;align-items:center;gap:8px;margin-bottom:6px;font-weight:700;color:#0b6b35;font-size:.92rem\"\u003e\r\n                  \u003cspan aria-hidden=\"true\"\u003e\u0026#128101;\u003c/span\u003e Equipo de trabajo de esta actividad\r\n                \u003c/div\u003e\r\n                \u003cp class=\"intro-text\" style=\"margin:0 0 10px;font-size:.84rem;color:#455a64;line-height:1.55\"\u003e\r\n                  Esta actividad se trabaja en equipo de \u003cstrong\u003e3 aprendices\u003c/strong\u003e. Configura aqu\u0026iacute; tu equipo para 3.2.2; puede ser diferente al de las actividades 3.1.2 y 3.2.1.\r\n                \u003c/p\u003e\r\n                \u003cdiv id=\"equipoGuia3Summary_mapa322\"\u003e\u003c/div\u003e\r\n                \u003cdiv id=\"equipoGuia3Config_mapa322\" style=\"display:none\"\u003e\r\n                  \u003cdiv style=\"margin:6px 0 6px;font-weight:600;font-size:.86rem;color:#1b5e20\"\u003eSelecciona a tus 2 compa\u0026ntilde;eros (tu nombre ya est\u0026aacute; incluido):\u003c/div\u003e\r\n                  \u003cdiv id=\"equipoGuia3RosterMount_mapa322\" style=\"display:flex;flex-direction:column;gap:6px;max-height:240px;overflow:auto;padding:8px 10px;border:1px solid #cfe0d3;border-radius:8px;background:#ffffff\"\u003e\u003c/div\u003e\r\n                  \u003cdiv id=\"equipoGuia3FormHint_mapa322\" class=\"intro-text\" style=\"margin:8px 0 0;font-size:.82rem;color:#4b5563\"\u003eCargando roster de la ficha\u0026hellip;\u003c/div\u003e\r\n                  \u003cdiv class=\"act-btn-group\" style=\"margin-top:10px;display:flex;gap:8px;flex-wrap:wrap\"\u003e\r\n                    \u003cbutton type=\"button\" onclick=\"confirmarEquipoGuia3('mapa322')\" class=\"btn-save-response\"\u003e\u0026#128101; Confirmar equipo\u003c/button\u003e\r\n                    \u003cbutton type=\"button\" onclick=\"cancelarEquipoGuia3Config('mapa322')\" style=\"padding:8px 16px;border:1px solid #cfe0d3;background:#ffffff;color:#37474f;border-radius:6px;font-family:inherit;font-size:.88rem;cursor:pointer\"\u003eCancelar\u003c/button\u003e\r\n                  \u003c/div\u003e\r\n                \u003c/div\u003e\r\n              \u003c/div\u003e\r\n\r\n              \u003carticle class=\"support-card\" style=\"margin-top:14px\"\u003e\r\n                \u003ch3\u003e\u0026#10067; \u0026iquest;Qu\u0026eacute; es un mapa conceptual?\u003c/h3\u003e\r\n                \u003cp style=\"margin:0 0 6px;line-height:1.6\"\u003e\r\n                  Un \u003cstrong\u003emapa conceptual\u003c/strong\u003e es un dibujo que muestra c\u0026oacute;mo se relacionan\r\n                  ideas o conceptos. Tiene tres partes:\r\n                \u003c/p\u003e\r\n                \u003cul style=\"padding-left:1.3rem;margin:0;line-height:1.7\"\u003e\r\n                  \u003cli\u003e\u003cstrong\u003eConceptos:\u003c/strong\u003e palabras o frases cortas encerradas en \u0026oacute;valos o cajas (ej: \u003cem\u003eantivirus\u003c/em\u003e, \u003cem\u003eficha t\u0026eacute;cnica\u003c/em\u003e, \u003cem\u003einventario\u003c/em\u003e).\u003c/li\u003e\r\n                  \u003cli\u003e\u003cstrong\u003eL\u0026iacute;neas o flechas:\u003c/strong\u003e conectan dos conceptos para mostrar que se relacionan.\u003c/li\u003e\r\n                  \u003cli\u003e\u003cstrong\u003ePalabras de enlace:\u003c/strong\u003e verbos cortos que se escriben sobre la l\u0026iacute;nea para explicar la relaci\u0026oacute;n (ej: \u003cem\u003esirve para\u003c/em\u003e, \u003cem\u003ese documenta con\u003c/em\u003e, \u003cem\u003eincluye\u003c/em\u003e, \u003cem\u003erequiere\u003c/em\u003e).\u003c/li\u003e\r\n                \u003c/ul\u003e\r\n              \u003c/article\u003e\r\n\r\n              \u003carticle class=\"support-card\" style=\"margin-top:14px\"\u003e\r\n                \u003ch3\u003e\u0026#128205; Pasos para construir el mapa\u003c/h3\u003e\r\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.75\"\u003e\r\n                  \u003cli\u003eRe\u0026uacute;nanse con sus 2 compa\u0026ntilde;eros de equipo y revisen sus apuntes de los Bloques A y B.\u003c/li\u003e\r\n                  \u003cli\u003eCompleten el \u003cstrong\u003ePanel de planeaci\u0026oacute;n\u003c/strong\u003e de aqu\u0026iacute; abajo (6 campos). No avancen al dibujo sin terminar este paso.\u003c/li\u003e\r\n                  \u003cli\u003ePresionen \u003cstrong\u003eGuardar planeaci\u0026oacute;n\u003c/strong\u003e. Pueden tambi\u0026eacute;n exportarla a Word como apoyo.\u003c/li\u003e\r\n                  \u003cli\u003eDibujen el mapa en CmapTools (digital) o en cartulina (f\u0026iacute;sico), respetando la planeaci\u0026oacute;n.\u003c/li\u003e\r\n                  \u003cli\u003eComparen su mapa con la \u003cstrong\u003eLista de verificaci\u0026oacute;n\u003c/strong\u003e al final. Si falta algo, ajusten.\u003c/li\u003e\r\n                  \u003cli\u003eExporten el mapa a PDF (o tomen foto del mapa f\u0026iacute;sico) y suban a Drive desde el bot\u0026oacute;n del final.\u003c/li\u003e\r\n                \u003c/ol\u003e\r\n              \u003c/article\u003e\r\n\r\n              \u003carticle class=\"support-card\" style=\"margin-top:14px;background:#fffbe6;border-color:#f3e0a3\"\u003e\r\n                \u003ch3 style=\"color:#8a6d00;margin:0 0 6px\"\u003e\u0026#128064; Ejemplo interactivo \u0026mdash; constr\u0026uacute;yelo paso a paso\u003c/h3\u003e\r\n                \u003cp style=\"margin:0 0 10px;font-size:.84rem;color:#5a4500;line-height:1.55\"\u003e\r\n                  Pulsa \u003cstrong\u003eSiguiente\u003c/strong\u003e para ir construyendo el mapa por capas. As\u0026iacute; ves c\u0026oacute;mo el equipo arma la planeaci\u0026oacute;n antes de dibujar (no es la respuesta, solo una idea).\r\n                \u003c/p\u003e\r\n\r\n                \u003cstyle\u003e\r\n                  /* Estilos del mapa conceptual demo (alcance: .cm-demo-*) */\r\n                  .cm-demo-controls{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:10px}\r\n                  .cm-demo-btn{display:inline-flex;align-items:center;gap:4px;padding:6px 14px;border:1px solid #c79a00;background:#fff;color:#5a4500;border-radius:6px;font-family:inherit;font-size:.84rem;font-weight:600;cursor:pointer;transition:all .15s ease}\r\n                  .cm-demo-btn:hover{background:#fffbe6;transform:translateY(-1px)}\r\n                  .cm-demo-btn:disabled{opacity:.4;cursor:not-allowed;transform:none}\r\n                  .cm-demo-btn.primary{background:#8a6d00;color:#fff;border-color:#8a6d00}\r\n                  .cm-demo-btn.primary:hover{background:#5a4500}\r\n                  .cm-demo-step-label{margin-left:auto;font-weight:700;color:#5a4500;font-size:.84rem;padding:4px 10px;background:#fff;border:1px solid #f3e0a3;border-radius:12px}\r\n                  .cm-demo-stage{position:relative;width:100%;background:#ffffff;border:1px solid #f3e0a3;border-radius:8px;padding:8px;overflow:auto}\r\n                  .cm-demo-svg{width:100%;height:auto;min-height:340px;display:block;font-family:Arial,Helvetica,sans-serif}\r\n                  .cm-node rect{fill:#ffffff;stroke:#1b5e20;stroke-width:2;transition:all .25s ease}\r\n                  .cm-node text{font-size:13px;pointer-events:none}\r\n                  .cm-node.central rect{fill:#1b5e20;stroke:#0b3d18}\r\n                  .cm-node.central text{fill:#ffffff;font-weight:700;font-size:14px}\r\n                  .cm-node.branch rect{fill:#e8f5e9;stroke:#1b5e20}\r\n                  .cm-node.branch text{fill:#0b6b35;font-weight:600}\r\n                  .cm-node.leaf rect{fill:#fff7e6;stroke:#c79a00}\r\n                  .cm-node.leaf text{fill:#5a4500}\r\n                  .cm-node.aplic rect{fill:#e3f2fd;stroke:#0d47a1}\r\n                  .cm-node.aplic text{fill:#0d47a1}\r\n                  .cm-node:hover rect{stroke-width:3;filter:drop-shadow(0 3px 6px rgba(0,0,0,.18))}\r\n                  .cm-line{stroke:#1b5e20;stroke-width:2;fill:none}\r\n                  .cm-line.leaf-line{stroke:#c79a00;stroke-dasharray:4 3}\r\n                  .cm-line.aplic-line{stroke:#0d47a1;stroke-dasharray:6 4}\r\n                  .cm-edge-label{font-size:11px;font-style:italic;fill:#5a4500;font-weight:600}\r\n                  .cm-layer{opacity:0;transform:translateY(10px);transition:opacity .5s ease,transform .5s ease;pointer-events:none}\r\n                  .cm-layer.cm-on{opacity:1;transform:translateY(0);pointer-events:auto}\r\n                  .cm-hint{font-size:11px;fill:#9a8a4a;font-style:italic}\r\n                \u003c/style\u003e\r\n\r\n                \u003cdiv class=\"cm-demo-controls\"\u003e\r\n                  \u003cbutton type=\"button\" class=\"cm-demo-btn\" id=\"cmDemoPrev\" onclick=\"cmDemoStep(-1)\"\u003e\u0026#9664; Anterior\u003c/button\u003e\r\n                  \u003cbutton type=\"button\" class=\"cm-demo-btn primary\" id=\"cmDemoNext\" onclick=\"cmDemoStep(1)\"\u003eSiguiente \u0026#9654;\u003c/button\u003e\r\n                  \u003cbutton type=\"button\" class=\"cm-demo-btn\" id=\"cmDemoReset\" onclick=\"cmDemoReset()\"\u003e\u0026#8634; Reiniciar\u003c/button\u003e\r\n                  \u003cbutton type=\"button\" class=\"cm-demo-btn\" id=\"cmDemoPlay\" onclick=\"cmDemoPlay()\"\u003e\u0026#9654;\u0026#9654; Reproducir\u003c/button\u003e\r\n                  \u003cspan class=\"cm-demo-step-label\" id=\"cmDemoStepLabel\"\u003ePaso 1 de 4\u003c/span\u003e\r\n                \u003c/div\u003e\r\n\r\n                \u003cdiv class=\"cm-demo-stage\"\u003e\r\n                  \u003csvg id=\"cmDemoSvg\" class=\"cm-demo-svg\" viewBox=\"0 0 760 540\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\" aria-label=\"Mapa conceptual de ejemplo\"\u003e\r\n                    \u003cg class=\"cm-layer cm-on\" data-step=\"1\"\u003e\r\n                      \u003cg class=\"cm-node central\"\u003e\r\n                        \u003crect x=\"200\" y=\"20\" width=\"360\" height=\"56\" rx=\"28\"/\u003e\r\n                        \u003ctext x=\"380\" y=\"44\" text-anchor=\"middle\"\u003eHerramientas tecnol\u0026oacute;gicas\u003c/text\u003e\r\n                        \u003ctext x=\"380\" y=\"62\" text-anchor=\"middle\"\u003een una MiPyme\u003c/text\u003e\r\n                      \u003c/g\u003e\r\n                    \u003c/g\u003e\r\n\r\n                    \u003cg class=\"cm-layer\" data-step=\"2\"\u003e\r\n                      \u003cline class=\"cm-line\" x1=\"380\" y1=\"76\" x2=\"130\" y2=\"180\"/\u003e\r\n                      \u003cline class=\"cm-line\" x1=\"380\" y1=\"76\" x2=\"380\" y2=\"180\"/\u003e\r\n                      \u003cline class=\"cm-line\" x1=\"380\" y1=\"76\" x2=\"630\" y2=\"180\"/\u003e\r\n                      \u003ctext class=\"cm-edge-label\" x=\"220\" y=\"130\" text-anchor=\"middle\"\u003eincluye\u003c/text\u003e\r\n                      \u003ctext class=\"cm-edge-label\" x=\"395\" y=\"130\"\u003esigue\u003c/text\u003e\r\n                      \u003ctext class=\"cm-edge-label\" x=\"540\" y=\"130\" text-anchor=\"middle\"\u003egenera\u003c/text\u003e\r\n\r\n                      \u003cg class=\"cm-node branch\"\u003e\r\n                        \u003crect x=\"40\" y=\"180\" width=\"180\" height=\"46\" rx=\"23\"/\u003e\r\n                        \u003ctext x=\"130\" y=\"208\" text-anchor=\"middle\"\u003eSoftware ofim\u0026aacute;tico\u003c/text\u003e\r\n                      \u003c/g\u003e\r\n                      \u003cg class=\"cm-node branch\"\u003e\r\n                        \u003crect x=\"290\" y=\"180\" width=\"180\" height=\"46\" rx=\"23\"/\u003e\r\n                        \u003ctext x=\"380\" y=\"208\" text-anchor=\"middle\"\u003eProcesos t\u0026eacute;cnicos\u003c/text\u003e\r\n                      \u003c/g\u003e\r\n                      \u003cg class=\"cm-node branch\"\u003e\r\n                        \u003crect x=\"540\" y=\"180\" width=\"180\" height=\"46\" rx=\"23\"/\u003e\r\n                        \u003ctext x=\"630\" y=\"208\" text-anchor=\"middle\"\u003eDocumentaci\u0026oacute;n\u003c/text\u003e\r\n                      \u003c/g\u003e\r\n                    \u003c/g\u003e\r\n\r\n                    \u003cg class=\"cm-layer\" data-step=\"3\"\u003e\r\n                      \u003cline class=\"cm-line leaf-line\" x1=\"130\" y1=\"226\" x2=\"130\" y2=\"290\"/\u003e\r\n                      \u003cline class=\"cm-line leaf-line\" x1=\"380\" y1=\"226\" x2=\"380\" y2=\"290\"/\u003e\r\n                      \u003cline class=\"cm-line leaf-line\" x1=\"630\" y1=\"226\" x2=\"630\" y2=\"290\"/\u003e\r\n                      \u003ctext class=\"cm-edge-label\" x=\"142\" y=\"262\"\u003ecomo\u003c/text\u003e\r\n                      \u003ctext class=\"cm-edge-label\" x=\"390\" y=\"262\"\u003epor ejemplo\u003c/text\u003e\r\n                      \u003ctext class=\"cm-edge-label\" x=\"640\" y=\"262\"\u003etales como\u003c/text\u003e\r\n\r\n                      \u003cg class=\"cm-node leaf\"\u003e\r\n                        \u003crect x=\"30\" y=\"290\" width=\"200\" height=\"80\" rx=\"8\"/\u003e\r\n                        \u003ctext x=\"130\" y=\"316\" text-anchor=\"middle\"\u003eLibreOffice\u003c/text\u003e\r\n                        \u003ctext x=\"130\" y=\"338\" text-anchor=\"middle\"\u003eAntivirus\u003c/text\u003e\r\n                        \u003ctext x=\"130\" y=\"360\" text-anchor=\"middle\"\u003eCPU-Z, CrystalDiskInfo\u003c/text\u003e\r\n                      \u003c/g\u003e\r\n                      \u003cg class=\"cm-node leaf\"\u003e\r\n                        \u003crect x=\"280\" y=\"290\" width=\"200\" height=\"80\" rx=\"8\"/\u003e\r\n                        \u003ctext x=\"380\" y=\"316\" text-anchor=\"middle\"\u003eInstalaci\u0026oacute;n\u003c/text\u003e\r\n                        \u003ctext x=\"380\" y=\"338\" text-anchor=\"middle\"\u003eConfiguraci\u0026oacute;n\u003c/text\u003e\r\n                        \u003ctext x=\"380\" y=\"360\" text-anchor=\"middle\"\u003eDiagn\u0026oacute;stico\u003c/text\u003e\r\n                      \u003c/g\u003e\r\n                      \u003cg class=\"cm-node leaf\"\u003e\r\n                        \u003crect x=\"530\" y=\"290\" width=\"200\" height=\"80\" rx=\"8\"/\u003e\r\n                        \u003ctext x=\"630\" y=\"316\" text-anchor=\"middle\"\u003eFicha t\u0026eacute;cnica\u003c/text\u003e\r\n                        \u003ctext x=\"630\" y=\"338\" text-anchor=\"middle\"\u003eInventario\u003c/text\u003e\r\n                        \u003ctext x=\"630\" y=\"360\" text-anchor=\"middle\"\u003eChecklist\u003c/text\u003e\r\n                      \u003c/g\u003e\r\n                    \u003c/g\u003e\r\n\r\n                    \u003cg class=\"cm-layer\" data-step=\"4\"\u003e\r\n                      \u003cpath class=\"cm-line aplic-line\" d=\"M 130 370 Q 240 430 380 440\"/\u003e\r\n                      \u003cpath class=\"cm-line aplic-line\" d=\"M 380 370 L 380 440\"/\u003e\r\n                      \u003cpath class=\"cm-line aplic-line\" d=\"M 630 370 Q 520 430 380 440\"/\u003e\r\n                      \u003ctext class=\"cm-edge-label\" x=\"380\" y=\"420\" text-anchor=\"middle\" style=\"fill:#0d47a1\"\u003ese aplican juntos en\u003c/text\u003e\r\n\r\n                      \u003cg class=\"cm-node aplic\"\u003e\r\n                        \u003crect x=\"80\" y=\"440\" width=\"600\" height=\"80\" rx=\"12\"/\u003e\r\n                        \u003ctext x=\"380\" y=\"464\" text-anchor=\"middle\" font-weight=\"700\"\u003eFerreter\u0026iacute;a \"El Trinche\" - Puerto Boyac\u0026aacute;\u003c/text\u003e\r\n                        \u003ctext x=\"380\" y=\"486\" text-anchor=\"middle\"\u003eEl antivirus + LibreOffice se documentan en una ficha t\u0026eacute;cnica\u003c/text\u003e\r\n                        \u003ctext x=\"380\" y=\"506\" text-anchor=\"middle\" class=\"cm-hint\"\u003epara que el due\u0026ntilde;o sepa qu\u0026eacute; tiene instalado y cu\u0026aacute;ndo renovarlo.\u003c/text\u003e\r\n                      \u003c/g\u003e\r\n                    \u003c/g\u003e\r\n                  \u003c/svg\u003e\r\n                \u003c/div\u003e\r\n\r\n                \u003cp style=\"margin:10px 0 0;font-size:.82rem;color:#5a4500;line-height:1.55\"\u003e\r\n                  \u0026#128172; Cada \u003cstrong\u003e\u0026oacute;valo verde\u003c/strong\u003e es un concepto, los \u003cstrong\u003everbos en cursiva\u003c/strong\u003e sobre las l\u0026iacute;neas son palabras de enlace, las \u003cstrong\u003ecajas amarillas\u003c/strong\u003e son sub-conceptos y la \u003cstrong\u003ecaja azul\u003c/strong\u003e final es la aplicaci\u0026oacute;n concreta en una empresa real.\r\n                \u003c/p\u003e\r\n              \u003c/article\u003e\r\n\r\n              \u003carticle class=\"notes-card\" style=\"margin-top:18px\"\u003e\r\n                \u003ch3\u003e\u0026#128221; Panel de planeaci\u0026oacute;n del mapa (trabajo en equipo)\u003c/h3\u003e\r\n                \u003cp class=\"intro-text\" style=\"margin:0 0 10px;font-size:.86rem;color:#455a64;line-height:1.55\"\u003e\r\n                  Completen los 6 campos en equipo. Esta planeaci\u0026oacute;n queda guardada y la pueden\r\n                  exportar a Word para usarla como gu\u0026iacute;a mientras dibujan el mapa.\r\n                \u003c/p\u003e\r\n\r\n                \u003clabel\u003e\r\n                  \u003cspan\u003e\u003cstrong\u003e1. Concepto central\u003c/strong\u003e (la palabra o frase que ir\u0026aacute; en el centro del mapa)\u003c/span\u003e\r\n                  \u003cinput type=\"text\" data-store=\"mapa322_central\" data-track placeholder=\"Ej.: Herramientas tecnol\u0026oacute;gicas para soporte t\u0026eacute;cnico\"\u003e\r\n                \u003c/label\u003e\r\n\r\n                \u003clabel\u003e\r\n                  \u003cspan\u003e\u003cstrong\u003e2. Ramas principales\u003c/strong\u003e (4 a 5 categor\u0026iacute;as que se desprenden del centro \u0026mdash; una por l\u0026iacute;nea)\u003c/span\u003e\r\n                  \u003ctextarea rows=\"4\" data-store=\"mapa322_ramas\" data-track placeholder=\"Ej.:\u0026#10;1) Software ofim\u0026aacute;tico\u0026#10;2) Herramientas de diagn\u0026oacute;stico\u0026#10;3) Seguridad y antivirus\u0026#10;4) Documentaci\u0026oacute;n t\u0026eacute;cnica\u0026#10;5) Gesti\u0026oacute;n de cuentas\"\u003e\u003c/textarea\u003e\r\n                \u003c/label\u003e\r\n\r\n                \u003clabel\u003e\r\n                  \u003cspan\u003e\u003cstrong\u003e3. Sub-conceptos\u003c/strong\u003e que NO pueden faltar (m\u0026iacute;nimo 10 t\u0026eacute;rminos distribuidos entre las ramas)\u003c/span\u003e\r\n                  \u003ctextarea rows=\"5\" data-store=\"mapa322_subconceptos\" data-track placeholder=\"Ej.: LibreOffice, Microsoft 365, CPU-Z, CrystalDiskInfo, antivirus, ficha t\u0026eacute;cnica, hoja de vida del equipo, inventario, checklist, convenci\u0026oacute;n de nombres, manual t\u0026eacute;cnico...\"\u003e\u003c/textarea\u003e\r\n                \u003c/label\u003e\r\n\r\n                \u003clabel\u003e\r\n                  \u003cspan\u003e\u003cstrong\u003e4. Palabras de enlace\u003c/strong\u003e que usar\u0026aacute;n (m\u0026iacute;nimo 5 verbos distintos; van sobre las l\u0026iacute;neas)\u003c/span\u003e\r\n                  \u003ctextarea rows=\"3\" data-store=\"mapa322_enlaces\" data-track placeholder=\"Ej.: incluye, sirve para, se documenta con, requiere, se relaciona con, se aplica a, genera, depende de...\"\u003e\u003c/textarea\u003e\r\n                \u003c/label\u003e\r\n\r\n                \u003clabel\u003e\r\n                  \u003cspan\u003e\u003cstrong\u003e5. Aplicaci\u0026oacute;n concreta en una empresa local\u003c/strong\u003e (un ejemplo real con nombre del negocio: ferreter\u0026iacute;a, droguer\u0026iacute;a, taller, granja, papeler\u0026iacute;a, etc.)\u003c/span\u003e\r\n                  \u003ctextarea rows=\"3\" data-store=\"mapa322_aplicacion\" data-track placeholder=\"Ej.: En la ferreter\u0026iacute;a 'El Trinche' de Puerto Boyac\u0026aacute;, el inventario de software (LibreOffice + antivirus) se documenta en una ficha t\u0026eacute;cnica para que el due\u0026ntilde;o sepa qu\u0026eacute; tiene instalado en cada equipo y cu\u0026aacute;ndo renovarlo.\"\u003e\u003c/textarea\u003e\r\n                \u003c/label\u003e\r\n\r\n                \u003clabel\u003e\r\n                  \u003cspan\u003e\u003cstrong\u003e6. Herramienta elegida\u003c/strong\u003e para dibujar el mapa\u003c/span\u003e\r\n                  \u003cselect data-store=\"mapa322_herramienta\" data-track\u003e\r\n                    \u003coption value=\"\"\u003e-- Seleccionen una opci\u0026oacute;n --\u003c/option\u003e\r\n                    \u003coption value=\"CmapTools\"\u003eCmapTools (digital, recomendada)\u003c/option\u003e\r\n                    \u003coption value=\"LibreOffice Draw\"\u003eLibreOffice Draw (digital)\u003c/option\u003e\r\n                    \u003coption value=\"Lucidchart\"\u003eLucidchart (web)\u003c/option\u003e\r\n                    \u003coption value=\"Canva\"\u003eCanva (web)\u003c/option\u003e\r\n                    \u003coption value=\"Cartulina\"\u003eCartulina con marcadores (f\u0026iacute;sico, luego foto)\u003c/option\u003e\r\n                    \u003coption value=\"Otro\"\u003eOtro (acordar con el instructor)\u003c/option\u003e\r\n                  \u003c/select\u003e\r\n                \u003c/label\u003e\r\n\r\n                \u003cdiv id=\"mapa322DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\r\n                \u003cdiv class=\"act-btn-group\"\u003e\r\n                  \u003cbutton type=\"button\" id=\"btnGuardarMapa322\"\r\n                    onclick=\"guardarMapa322()\"\r\n                    class=\"btn-save-response\"\u003e\r\n                    \u0026#128190; Guardar planeaci\u0026oacute;n\r\n                  \u003c/button\u003e\r\n                  \u003cbutton class=\"btn-export-word\" type=\"button\" onclick=\"exportarMapa322Word()\"\u003e\r\n                    \u0026#128196; Exportar planeaci\u0026oacute;n a Word\r\n                  \u003c/button\u003e\r\n                \u003c/div\u003e\r\n                \u003cdiv id=\"mapa322Status\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\r\n                  \u0026#9989; Planeaci\u0026oacute;n guardada correctamente. Ahora pueden dibujar el mapa siguiendo esta planeaci\u0026oacute;n.\r\n                \u003c/div\u003e\r\n              \u003c/article\u003e\r\n\r\n              \u003carticle class=\"support-card\" style=\"margin-top:18px;background:#f1f9f3;border-color:#cfe0d3\"\u003e\r\n                \u003ch3 style=\"color:#0b6b35\"\u003e\u0026#9989; Lista de verificaci\u0026oacute;n del mapa terminado\u003c/h3\u003e\r\n                \u003cp style=\"margin:0 0 8px;font-size:.86rem;color:#455a64\"\u003eAntes de subir el mapa a Drive, asegurense de que tenga:\u003c/p\u003e\r\n                \u003cul style=\"padding-left:1.3rem;margin:0;line-height:1.8\"\u003e\r\n                  \u003cli\u003eUn solo \u003cstrong\u003econcepto central\u003c/strong\u003e claramente identificado.\u003c/li\u003e\r\n                  \u003cli\u003eAl menos \u003cstrong\u003e4 ramas principales\u003c/strong\u003e diferentes.\u003c/li\u003e\r\n                  \u003cli\u003e\u003cstrong\u003eM\u0026iacute;nimo 10 sub-conceptos\u003c/strong\u003e distribuidos entre las ramas.\u003c/li\u003e\r\n                  \u003cli\u003ePalabras de enlace sobre las \u003cstrong\u003el\u0026iacute;neas o flechas\u003c/strong\u003e.\u003c/li\u003e\r\n                  \u003cli\u003eConceptos de herramientas tecnol\u0026oacute;gicas (Bloque A) y de documentaci\u0026oacute;n t\u0026eacute;cnica (Bloque B).\u003c/li\u003e\r\n                  \u003cli\u003eUna relaci\u0026oacute;n visible: \u003cstrong\u003eherramienta \u0026rarr; procedimiento \u0026rarr; registro documentado\u003c/strong\u003e.\u003c/li\u003e\r\n                  \u003cli\u003eNombre del equipo o de los integrantes en una esquina del mapa.\u003c/li\u003e\r\n                \u003c/ul\u003e\r\n              \u003c/article\u003e\r\n\r\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\r\n                \u003cdiv class=\"label\"\u003e\u0026#128228; C\u0026oacute;mo entregar\u003c/div\u003e\r\n                \u003col style=\"padding-left:1.3rem;margin:6px 0 0;line-height:1.7\"\u003e\r\n                  \u003cli\u003eSi el mapa es digital: exportenlo a PDF (Archivo \u0026rarr; Exportar a PDF).\u003c/li\u003e\r\n                  \u003cli\u003eSi el mapa es f\u0026iacute;sico: tomen una foto clara y la guardan como JPG o PDF.\u003c/li\u003e\r\n                  \u003cli\u003eBajen al final de esta actividad y pulsen \u003cstrong\u003eSubir al portafolio de Drive\u003c/strong\u003e. El sistema asigna autom\u0026aacute;ticamente la carpeta de su equipo.\u003c/li\u003e\r\n                \u003c/ol\u003e\r\n              \u003c/div\u003e\r\n\r\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\r\n                \u003cdiv class=\"label\"\u003e\u0026#128204; Herramientas recomendadas\u003c/div\u003e\r\n                \u003cp style=\"margin:0\"\u003e\r\n                  \u003cstrong\u003eCmapTools\u003c/strong\u003e (\u003ca href=\"https://cmap.ihmc.us\" target=\"_blank\" rel=\"noopener\"\u003ehttps://cmap.ihmc.us\u003c/a\u003e)\r\n                  \u0026mdash; gratuito, funciona sin conexi\u0026oacute;n; debe instalarse previamente por el instructor.\r\n                  \u003cstrong\u003eAlternativa f\u0026iacute;sica:\u003c/strong\u003e elaborar el mapa en cartulina con marcadores y registrar evidencia fotogr\u0026aacute;fica.\r\n                \u003c/p\u003e\r\n              \u003c/div\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n        \u003c/div\u003e\r\n      \u003c/div\u003e\r\n\r\n      \u003cdiv id=\"apropiacion\" class=\"section-title\"\u003e3.3 \u0026middot; Actividades de Apropiaci\u0026oacute;n del Conocimiento\u003c/div\u003e\r\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\r\n        \u003cp\u003e\r\n          En esta etapa pondr\u0026aacute;s en pr\u0026aacute;ctica los conocimientos adquiridos.\r\n          Realizar\u0026aacute;s ejercicios t\u0026eacute;cnicos que simulan situaciones reales del entorno\r\n          laboral de las MiPymes. Trabaja con cuidado: las evidencias que generes aqu\u0026iacute; son\r\n          evaluables.\r\n        \u003c/p\u003e\r\n      \u003c/div\u003e\r\n      \u003cdiv class=\"card open cat-apropiacion\"\u003e\r\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\r\n          \u003cdiv class=\"card-header-left\"\u003e\r\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128218;\u003c/div\u003e\r\n            \u003cdiv\u003e\r\n              \u003ch3\u003eActividades de Apropiaci\u0026oacute;n\u003c/h3\u003e\r\n              \u003cp\u003e3 actividades\u003c/p\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n        \u003c/div\u003e\r\n        \u003cdiv class=\"card-body\"\u003e\r\n          \u003cdiv class=\"activity open mission-card\"\u003e\r\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\r\n              \u003cspan class=\"activity-num\"\u003e3.3.1\u003c/span\u003e\r\n              \u003cspan class=\"activity-title\"\u003e\u0026#9881;\u0026#65039; Instalaci\u0026oacute;n y configuraci\u0026oacute;n de herramientas tecnol\u0026oacute;gicas (RAP 02)\u003c/span\u003e\r\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n            \u003c/div\u003e\r\n            \u003cdiv class=\"activity-body\"\u003e\r\n              \u003cp class=\"intro-text\"\u003e\r\n                Siguiendo el manual t\u0026eacute;cnico suministrado por el instructor, instala y\r\n                configura un conjunto de herramientas inform\u0026aacute;ticas en un equipo de\r\n                c\u0026oacute;mputo, simulando la preparaci\u0026oacute;n de un puesto de trabajo para una\r\n                MiPyme.\r\n              \u003c/p\u003e\r\n\r\n              \u003carticle class=\"support-card\"\u003e\r\n                \u003ch3\u003eHerramientas que debes instalar y configurar:\u003c/h3\u003e\r\n                \u003cul style=\"padding-left:1.3rem;margin:0;line-height:1.85\"\u003e\r\n                  \u003cli\u003e\r\n                    \u003cstrong\u003eSuite ofim\u0026aacute;tica (LibreOffice):\u003c/strong\u003e procesador de texto\r\n                    (Writer), hoja de c\u0026aacute;lculo (Calc) y presentaciones (Impress).\r\n                    Versi\u0026oacute;n gratuita compatible con formatos .docx, .xlsx y .pptx.\r\n                  \u003c/li\u003e\r\n                  \u003cli\u003eNavegador web actualizado con extensiones b\u0026aacute;sicas de seguridad (bloqueador de anuncios, HTTPS).\u003c/li\u003e\r\n                  \u003cli\u003eHerramienta de compresi\u0026oacute;n y descompresi\u0026oacute;n de archivos (7-Zip o WinRAR).\u003c/li\u003e\r\n                  \u003cli\u003eSoftware antivirus o protecci\u0026oacute;n integrada (Windows Defender configurado).\u003c/li\u003e\r\n                  \u003cli\u003eAl menos una herramienta de diagn\u0026oacute;stico de hardware/software (CPU-Z, CrystalDiskInfo u otra del documento \u0026lsquo;Herramientas de Diagn\u0026oacute;stico\u0026rsquo;).\u003c/li\u003e\r\n                \u003c/ul\u003e\r\n              \u003c/article\u003e\r\n\r\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\r\n                \u003ch3\u003ePara cada herramienta instalada debes:\u003c/h3\u003e\r\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.85\"\u003e\r\n                  \u003cli\u003eConsultar el manual t\u0026eacute;cnico o gu\u0026iacute;a de instalaci\u0026oacute;n oficial.\u003c/li\u003e\r\n                  \u003cli\u003eVerificar compatibilidad con el sistema operativo.\u003c/li\u003e\r\n                  \u003cli\u003eEjecutar el proceso de instalaci\u0026oacute;n paso a paso.\u003c/li\u003e\r\n                  \u003cli\u003eConfigurar los par\u0026aacute;metros b\u0026aacute;sicos seg\u0026uacute;n el manual.\u003c/li\u003e\r\n                  \u003cli\u003eVerificar que la herramienta funcione correctamente.\u003c/li\u003e\r\n                  \u003cli\u003eTomar captura de pantalla del programa abierto (\u003ckbd\u003eWin+Shift+S\u003c/kbd\u003e) y guardarla con el nombre indicado en cada tarjeta.\u003c/li\u003e\r\n                  \u003cli\u003eLlenar la ficha de la herramienta aqu\u0026iacute; abajo: versi\u0026oacute;n, configuraci\u0026oacute;n, resultado y observaciones.\u003c/li\u003e\r\n                \u003c/ol\u003e\r\n              \u003c/article\u003e\r\n\r\n              \u003carticle class=\"support-card\" style=\"margin-top:16px;background:#e3f2fd;border-color:#bbdefb\"\u003e\r\n                \u003ch3 style=\"color:#0d47a1\"\u003e\u0026#128193; Tu carpeta de evidencias\u003c/h3\u003e\r\n                \u003cp style=\"margin:0 0 6px;font-size:.88rem;color:#0d47a1;line-height:1.55\"\u003e\r\n                  Crea esta carpeta en tu PC \u003cstrong\u003eantes de empezar\u003c/strong\u003e. Guarda dentro las 5 capturas con los nombres exactos que aparecen en cada tarjeta. Despu\u0026eacute;s subir\u0026aacute;s esta carpeta a Drive desde el bot\u0026oacute;n \u0026laquo;Subir al portafolio de Drive\u0026raquo; al final.\r\n                \u003c/p\u003e\r\n                \u003ccode id=\"checklist331FolderHint\" style=\"display:block;font-family:Consolas,Monaco,monospace;font-size:.92rem;background:#fff;padding:8px 12px;border:1px solid #bbdefb;border-radius:6px;color:#0d47a1;word-break:break-all\"\u003eEvidencias_Act331_[tu-apellido_nombre]\u003c/code\u003e\r\n                \u003cbutton type=\"button\" onclick=\"copiarCarpetaChecklist331()\" class=\"btn-secondary\" style=\"margin-top:8px;display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border:1px solid #bbdefb;background:#fff;color:#0d47a1;border-radius:6px;font-family:inherit;font-size:.82rem;cursor:pointer;font-weight:600\"\u003e\r\n                  \u0026#128203; Copiar nombre de la carpeta\r\n                \u003c/button\u003e\r\n              \u003c/article\u003e\r\n\r\n              \u003carticle class=\"notes-card\" style=\"margin-top:18px\"\u003e\r\n                \u003ch3\u003e\u0026#128203; Bit\u0026aacute;cora de instalaci\u0026oacute;n (1 ficha por herramienta)\u003c/h3\u003e\r\n                \u003cp class=\"intro-text\" style=\"margin:0 0 10px;font-size:.86rem;color:#455a64;line-height:1.55\"\u003e\r\n                  Llena las 5 tarjetas a medida que vayas instalando cada herramienta. Si algo falla,\r\n                  anota el mensaje de error exacto y c\u0026oacute;mo lo resolviste \u0026mdash; eso tambi\u0026eacute;n es\r\n                  evidencia v\u0026aacute;lida.\r\n                \u003c/p\u003e\r\n                \u003cdiv id=\"checklist331Cards\" style=\"display:flex;flex-direction:column;gap:14px\"\u003e\u003c/div\u003e\r\n\r\n                \u003clabel style=\"margin-top:14px;display:block\"\u003e\r\n                  \u003cspan\u003e\u003cstrong\u003eReflexi\u0026oacute;n final\u003c/strong\u003e (m\u0026iacute;nimo 4 l\u0026iacute;neas): \u0026iquest;Qu\u0026eacute; fue lo m\u0026aacute;s dif\u0026iacute;cil de las instalaciones? \u0026iquest;Qu\u0026eacute; aprendiste que te servir\u0026aacute; en un trabajo real de soporte t\u0026eacute;cnico?\u003c/span\u003e\r\n                  \u003ctextarea rows=\"4\" data-store=\"checklist331_reflexion\" data-track placeholder=\"Ejemplo: La instalaci\u0026oacute;n de antivirus fue lo m\u0026aacute;s dif\u0026iacute;cil porque Windows Defender ya estaba activo y tuve que aprender a verificar su estado. Aprend\u0026iacute; que...\"\u003e\u003c/textarea\u003e\r\n                \u003c/label\u003e\r\n\r\n                \u003cdiv id=\"checklist331DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\r\n                \u003cdiv class=\"act-btn-group\"\u003e\r\n                  \u003cbutton type=\"button\" id=\"btnGuardarChecklist331\"\r\n                    onclick=\"guardarChecklist331()\"\r\n                    class=\"btn-save-response\"\u003e\r\n                    \u0026#128190; Guardar bit\u0026aacute;cora\r\n                  \u003c/button\u003e\r\n                  \u003cbutton class=\"btn-export-word\" type=\"button\" onclick=\"exportarChecklist331Word()\"\u003e\r\n                    \u0026#128196; Exportar bit\u0026aacute;cora a Word\r\n                  \u003c/button\u003e\r\n                \u003c/div\u003e\r\n                \u003cdiv id=\"checklist331Status\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\r\n                  \u0026#9989; Bit\u0026aacute;cora guardada correctamente. Recuerda subir la carpeta de evidencias a Drive desde el panel del final.\r\n                \u003c/div\u003e\r\n              \u003c/article\u003e\r\n\r\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\r\n                \u003cdiv class=\"label\"\u003e\u0026#128204; Recordatorio\u003c/div\u003e\r\n                \u003cp\u003e\r\n                  Descarga el software solo desde \u003cstrong\u003esitios web oficiales\u003c/strong\u003e de los\r\n                  fabricantes. Las herramientas que necesitas est\u0026aacute;n disponibles en el panel\r\n                  \u003cem\u003eMaterial de Apoyo\u003c/em\u003e de la barra lateral, ya descargadas de fuentes oficiales.\r\n                  Para capturas de pantalla usa \u003ckbd\u003eWin+Shift+S\u003c/kbd\u003e \u0026mdash; no necesitas instalar nada adicional.\r\n                \u003c/p\u003e\r\n              \u003c/div\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n\r\n          \u003cdiv class=\"activity mission-card\"\u003e\r\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\r\n              \u003cspan class=\"activity-num\"\u003e3.3.2\u003c/span\u003e\r\n              \u003cspan class=\"activity-title\"\u003e\u0026#128269; Diagn\u0026oacute;stico con herramientas de soporte t\u0026eacute;cnico (RAP 02)\u003c/span\u003e\r\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n            \u003c/div\u003e\r\n            \u003cdiv class=\"activity-body\"\u003e\r\n              \u003cp class=\"intro-text\"\u003e\r\n                Utilizando las herramientas de diagn\u0026oacute;stico instaladas, realiza un\r\n                an\u0026aacute;lisis completo del equipo de c\u0026oacute;mputo asignado. Este ejercicio\r\n                simula la labor de soporte t\u0026eacute;cnico que realizar\u0026iacute;as en una MiPyme.\r\n              \u003c/p\u003e\r\n\r\n              \u003carticle class=\"support-card\"\u003e\r\n                \u003ch3\u003eEl diagn\u0026oacute;stico debe incluir:\u003c/h3\u003e\r\n                \u003cul style=\"padding-left:1.3rem;margin:0;line-height:1.85\"\u003e\r\n                  \u003cli\u003eIdentificaci\u0026oacute;n del hardware: procesador, RAM, almacenamiento, tarjeta de red.\u003c/li\u003e\r\n                  \u003cli\u003eVerificaci\u0026oacute;n del sistema operativo: versi\u0026oacute;n, licenciamiento, actualizaciones pendientes.\u003c/li\u003e\r\n                  \u003cli\u003eEstado del disco duro: salud, fragmentaci\u0026oacute;n, espacio disponible.\u003c/li\u003e\r\n                  \u003cli\u003eInventario de software instalado: nombre, versi\u0026oacute;n, fecha de instalaci\u0026oacute;n, licencia.\u003c/li\u003e\r\n                  \u003cli\u003eConectividad de red: IP, m\u0026aacute;scara de subred, puerta de enlace, DNS, prueba de ping.\u003c/li\u003e\r\n                \u003c/ul\u003e\r\n              \u003c/article\u003e\r\n\r\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\r\n                \u003cdiv class=\"label\"\u003e\u0026#128204; Nota\u003c/div\u003e\r\n                \u003cp\u003e\r\n                  Herramientas recomendadas: CPU-Z (hardware), CrystalDiskInfo (disco),\r\n                  \u003ccode\u003emsinfo32\u003c/code\u003e (Win+R \u0026rarr; msinfo32, inventario nativo sin\r\n                  instalaci\u0026oacute;n), \u003ccode\u003eipconfig /all\u003c/code\u003e y \u003ccode\u003eping 8.8.8.8\u003c/code\u003e en\r\n                  CMD. Organiza todos los resultados en una carpeta:\r\n                  \u003cstrong\u003eDiagnostico_[TuNombre]_[Fecha]\u003c/strong\u003e. Nombra las capturas:\r\n                  \u003ccode\u003e01_CPU-Z_Hardware.png\u003c/code\u003e, \u003ccode\u003e02_CrystalDisk_Disco.png\u003c/code\u003e,\r\n                  \u003ccode\u003e03_msinfo32_Software.png\u003c/code\u003e, \u003ccode\u003e04_CMD_Red.png\u003c/code\u003e. Escribe un\r\n                  p\u0026aacute;rrafo de conclusi\u0026oacute;n en tu bit\u0026aacute;cora: \u0026iquest;el equipo\r\n                  est\u0026aacute; en buen estado para usarse en una empresa? \u0026iquest;Qu\u0026eacute;\r\n                  recomendar\u0026iacute;as mejorar?\r\n                \u003c/p\u003e\r\n              \u003c/div\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n\r\n          \u003cdiv class=\"activity mission-card\"\u003e\r\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\r\n              \u003cspan class=\"activity-num\"\u003e3.3.3\u003c/span\u003e\r\n              \u003cspan class=\"activity-title\"\u003e\u0026#128196; Documentaci\u0026oacute;n del proceso de gesti\u0026oacute;n de informaci\u0026oacute;n\u003c/span\u003e\r\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n            \u003c/div\u003e\r\n            \u003cdiv class=\"activity-body\"\u003e\r\n              \u003cp class=\"intro-text\"\u003e\r\n                Elabora un documento t\u0026eacute;cnico que registre de forma organizada el proceso\r\n                realizado en las actividades 3.3.1 y 3.3.2. Este documento es la evidencia\r\n                verificable de que el trabajo de instalaci\u0026oacute;n y diagn\u0026oacute;stico fue\r\n                ejecutado correctamente, y es parte esencial del perfil t\u0026eacute;cnico\r\n                profesional del t\u0026eacute;cnico en sistemas.\r\n              \u003c/p\u003e\r\n\r\n              \u003carticle class=\"support-card\"\u003e\r\n                \u003ch3\u003eEl documento debe contener obligatoriamente:\u003c/h3\u003e\r\n                \u003cul style=\"padding-left:1.3rem;margin:0;line-height:1.85\"\u003e\r\n                  \u003cli\u003e\u003cstrong\u003ePortada\u003c/strong\u003e con: t\u0026iacute;tulo, nombre del aprendiz, ficha, fecha y nombre del instructor.\u003c/li\u003e\r\n                  \u003cli\u003e\u003cstrong\u003eIntroducci\u0026oacute;n:\u003c/strong\u003e descripci\u0026oacute;n breve del objetivo del documento y del contexto organizacional.\u003c/li\u003e\r\n                  \u003cli\u003e\u003cstrong\u003eInventario de activos de software:\u003c/strong\u003e tabla con nombre, versi\u0026oacute;n, tipo de licencia, fecha de instalaci\u0026oacute;n, estado y observaciones de cada herramienta instalada.\u003c/li\u003e\r\n                  \u003cli\u003e\u003cstrong\u003eRegistro de procedimientos:\u003c/strong\u003e descripci\u0026oacute;n paso a paso de las instalaciones realizadas, con capturas de pantalla como evidencia.\u003c/li\u003e\r\n                  \u003cli\u003e\u003cstrong\u003eResultados del diagn\u0026oacute;stico t\u0026eacute;cnico:\u003c/strong\u003e tabla con los hallazgos del an\u0026aacute;lisis del equipo.\u003c/li\u003e\r\n                  \u003cli\u003e\u003cstrong\u003eEstructura de carpetas y convenci\u0026oacute;n de nombres:\u003c/strong\u003e c\u0026oacute;mo organizas los archivos y evidencias en el equipo.\u003c/li\u003e\r\n                  \u003cli\u003e\u003cstrong\u003eConclusiones y recomendaciones:\u003c/strong\u003e \u0026iquest;qu\u0026eacute; funcion\u0026oacute; bien?, \u0026iquest;qu\u0026eacute; mejorar\u0026iacute;as?, \u0026iquest;qu\u0026eacute; riesgos encontraste?\u003c/li\u003e\r\n                \u003c/ul\u003e\r\n              \u003c/article\u003e\r\n\r\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\r\n                \u003cdiv class=\"label\"\u003e\u0026#128204; Nota\u003c/div\u003e\r\n                \u003cp\u003e\r\n                  Usa LibreOffice Writer con la plantilla suministrada por el instructor. Aplica\r\n                  estilos de t\u0026iacute;tulo para que el documento sea navegable. Guarda versiones:\r\n                  \u003cstrong\u003eNombreDocumento_v1.0_AAAAMMDD\u003c/strong\u003e. Las capturas de pantalla se\r\n                  insertan directamente: Insertar \u0026rarr; Imagen. Si el documento pesa demasiado,\r\n                  comprime las im\u0026aacute;genes: clic derecho sobre la imagen \u0026rarr; Comprimir\r\n                  imagen.\r\n                \u003c/p\u003e\r\n              \u003c/div\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n\r\n        \u003c/div\u003e\r\n      \u003c/div\u003e\r\n\r\n      \u003cdiv id=\"transferencia\" class=\"section-title\"\u003e3.4 \u0026middot; Actividad de Transferencia del Conocimiento \u0026mdash; Actividad Integradora\u003c/div\u003e\r\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\r\n        \u003cp\u003e\r\n          Esta actividad integra todo lo aprendido y lo aplica directamente al contexto del\r\n          Proyecto Formativo. Simular\u0026aacute;s la labor de un t\u0026eacute;cnico de sistemas en una\r\n          MiPyme de Boyac\u0026aacute; que necesita implementar y presupuestar sus herramientas\r\n          tecnol\u0026oacute;gicas.\r\n        \u003c/p\u003e\r\n      \u003c/div\u003e\r\n      \u003cdiv class=\"card open cat-transferencia\"\u003e\r\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\r\n          \u003cdiv class=\"card-header-left\"\u003e\r\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128640;\u003c/div\u003e\r\n            \u003cdiv\u003e\r\n              \u003ch3\u003eActividades de Transferencia\u003c/h3\u003e\r\n              \u003cp\u003e2 actividades\u003c/p\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n        \u003c/div\u003e\r\n        \u003cdiv class=\"card-body\"\u003e\r\n          \u003cdiv class=\"activity open mission-card\"\u003e\r\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\r\n              \u003cspan class=\"activity-num\"\u003e3.4.1\u003c/span\u003e\r\n              \u003cspan class=\"activity-title\"\u003e\u0026#128188; Presupuesto de implementaci\u0026oacute;n tecnol\u0026oacute;gica (RAP 02)\u003c/span\u003e\r\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n            \u003c/div\u003e\r\n            \u003cdiv class=\"activity-body\"\u003e\r\n              \u003cp class=\"intro-text\"\u003e\r\n                Con base en el diagn\u0026oacute;stico y la implementaci\u0026oacute;n realizada, elabora un\r\n                documento en formato PDF con un presupuesto detallado de los elementos\r\n                requeridos para implementar un conjunto de herramientas tecnol\u0026oacute;gicas en la\r\n                infraestructura de una MiPyme.\r\n              \u003c/p\u003e\r\n\r\n              \u003carticle class=\"support-card\"\u003e\r\n                \u003ch3\u003eEl presupuesto debe incluir como m\u0026iacute;nimo:\u003c/h3\u003e\r\n                \u003cul style=\"padding-left:1.3rem;margin:0;line-height:1.85\"\u003e\r\n                  \u003cli\u003e\u003cstrong\u003eSoftware y licencias:\u003c/strong\u003e nombre, tipo de licencia (libre, propietaria, suscripci\u0026oacute;n), precio unitario, cantidad y total.\u003c/li\u003e\r\n                  \u003cli\u003e\u003cstrong\u003eHerramientas de diagn\u0026oacute;stico y soporte t\u0026eacute;cnico:\u003c/strong\u003e listado, precio y justificaci\u0026oacute;n t\u0026eacute;cnica.\u003c/li\u003e\r\n                  \u003cli\u003e\u003cstrong\u003eServicios en la nube (si aplica):\u003c/strong\u003e almacenamiento, correo corporativo, colaboraci\u0026oacute;n.\u003c/li\u003e\r\n                  \u003cli\u003e\u003cstrong\u003eTabla resumen\u003c/strong\u003e con: \u0026iacute;tem, descripci\u0026oacute;n, precio unitario, cantidad, total y justificaci\u0026oacute;n.\u003c/li\u003e\r\n                  \u003cli\u003e\u003cstrong\u003eConclusi\u0026oacute;n t\u0026eacute;cnica:\u003c/strong\u003e \u0026iquest;por qu\u0026eacute; seleccionaste esas herramientas para esa MiPyme?\u003c/li\u003e\r\n                \u003c/ul\u003e\r\n              \u003c/article\u003e\r\n\r\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\r\n                \u003cdiv class=\"label\"\u003e\u0026#128204; Nota \u0026mdash; Instrucciones\u003c/div\u003e\r\n                \u003col style=\"padding-left:1.3rem;margin:6px 0 0;line-height:1.85\"\u003e\r\n                  \u003cli\u003eAbre LibreOffice Calc y crea la tabla con las columnas: \u0026Iacute;tem, Descripci\u0026oacute;n, Tipo de licencia, Precio unitario (COP), Cantidad, Total, Justificaci\u0026oacute;n t\u0026eacute;cnica.\u003c/li\u003e\r\n                  \u003cli\u003e\r\n                    Investiga precios en sitios OFICIALES:\r\n                    \u003ca href=\"https://www.libreoffice.org\" target=\"_blank\" rel=\"noopener\"\u003elibreoffice.org\u003c/a\u003e (gratis),\r\n                    \u003ca href=\"https://www.7-zip.org\" target=\"_blank\" rel=\"noopener\"\u003e7-zip.org\u003c/a\u003e (gratis),\r\n                    \u003ca href=\"https://crystalmark.info\" target=\"_blank\" rel=\"noopener\"\u003ecrystalmark.info\u003c/a\u003e (gratis),\r\n                    \u003ca href=\"https://www.cpuid.com\" target=\"_blank\" rel=\"noopener\"\u003ecpuid.com\u003c/a\u003e (gratis). Anota siempre\r\n                    la URL del precio.\r\n                  \u003c/li\u003e\r\n                  \u003cli\u003eCompara al menos una opci\u0026oacute;n libre vs. una propietaria para la suite ofim\u0026aacute;tica. Justifica en la columna de justificaci\u0026oacute;n cu\u0026aacute;l elegiste y por qu\u0026eacute;.\u003c/li\u003e\r\n                  \u003cli\u003eUsa f\u0026oacute;rmulas: \u003ccode\u003e=precio*cantidad\u003c/code\u003e en la columna Total y \u003ccode\u003e=SUMA(...)\u003c/code\u003e para el total general.\u003c/li\u003e\r\n                  \u003cli\u003eEn una hoja separada llamada \u0026ldquo;Conclusi\u0026oacute;n\u0026rdquo;, responde en 5 l\u0026iacute;neas: \u0026iquest;por qu\u0026eacute; esas herramientas para esa empresa? \u0026iquest;Cu\u0026aacute;l priorizar\u0026iacute;as si el presupuesto fuera muy limitado?\u003c/li\u003e\r\n                  \u003cli\u003eExporta a PDF: Archivo \u0026rarr; Exportar como PDF. Nombre: \u003cstrong\u003ePresupuesto_MiPyme_[TuNombre].pdf\u003c/strong\u003e.\u003c/li\u003e\r\n                \u003c/ol\u003e\r\n              \u003c/div\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n\r\n          \u003cdiv class=\"activity mission-card\"\u003e\r\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\r\n              \u003cspan class=\"activity-num\"\u003e3.4.2\u003c/span\u003e\r\n              \u003cspan class=\"activity-title\"\u003e\u0026#127908; Presentaci\u0026oacute;n y sustentaci\u0026oacute;n oral\u003c/span\u003e\r\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n            \u003c/div\u003e\r\n            \u003cdiv class=\"activity-body\"\u003e\r\n              \u003cp class=\"intro-text\"\u003e\r\n                Presenta ante el grupo el trabajo realizado en las actividades 3.3.1, 3.3.2 y\r\n                3.3.3. Esta sustentaci\u0026oacute;n demuestra tu capacidad para explicar decisiones\r\n                t\u0026eacute;cnicas: qu\u0026eacute; instalaste, c\u0026oacute;mo lo verificaste y por\r\n                qu\u0026eacute; elegiste esas herramientas para la empresa.\r\n              \u003c/p\u003e\r\n\r\n              \u003carticle class=\"support-card\"\u003e\r\n                \u003ch3\u003eLa presentaci\u0026oacute;n debe:\u003c/h3\u003e\r\n                \u003cul style=\"padding-left:1.3rem;margin:0;line-height:1.85\"\u003e\r\n                  \u003cli\u003eDurar entre \u003cstrong\u003e8 y 12 minutos\u003c/strong\u003e.\u003c/li\u003e\r\n                  \u003cli\u003eExplicar qu\u0026eacute; herramientas instalaste, c\u0026oacute;mo lo hiciste y por qu\u0026eacute; tomaste esas decisiones.\u003c/li\u003e\r\n                  \u003cli\u003eMostrar la estructura del documento t\u0026eacute;cnico elaborado.\u003c/li\u003e\r\n                  \u003cli\u003eDescribir c\u0026oacute;mo aplicaste los protocolos de documentaci\u0026oacute;n en cada etapa.\u003c/li\u003e\r\n                  \u003cli\u003eSe\u0026ntilde;alar al menos \u003cstrong\u003euna lecci\u0026oacute;n aprendida\u003c/strong\u003e y \u003cstrong\u003euna mejora\u003c/strong\u003e que propondr\u0026iacute;as.\u003c/li\u003e\r\n                \u003c/ul\u003e\r\n              \u003c/article\u003e\r\n\r\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\r\n                \u003cdiv class=\"label\"\u003e\u0026#128204; Nota\u003c/div\u003e\r\n                \u003cp\u003e\r\n                  Herramienta digital sugerida: usa LibreOffice Impress para crear la\r\n                  presentaci\u0026oacute;n de apoyo. Limita las diapositivas a m\u0026aacute;ximo 10\r\n                  l\u0026aacute;minas con \u0026eacute;nfasis visual (no texto completo). No agregar\r\n                  animaciones ni transiciones.\r\n                \u003c/p\u003e\r\n              \u003c/div\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n\r\n        \u003c/div\u003e\r\n      \u003c/div\u003e\r\n\r\n      \u003cdiv id=\"evidencias\" class=\"section-title\"\u003ePlanteamiento de Evidencias de Aprendizaje\u003c/div\u003e\r\n      \u003cdiv class=\"card open cat-evaluacion\"\u003e\r\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\r\n          \u003cdiv class=\"card-header-left\"\u003e\r\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128202;\u003c/div\u003e\r\n            \u003cdiv\u003e\r\n              \u003ch3\u003eEvidencias y Criterios de Evaluaci\u0026oacute;n\u003c/h3\u003e\r\n              \u003cp\u003eResumen de productos, desempenos e instrumentos definidos para la guia\u003c/p\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n        \u003c/div\u003e\r\n        \u003cdiv class=\"card-body\"\u003e\r\n          \u003cdiv class=\"table-scroll\"\u003e\r\n            \u003ctable class=\"data-table\"\u003e\r\n              \u003cthead\u003e\r\n                \u003ctr\u003e\r\n                  \u003cth\u003eFase\u003c/th\u003e\r\n                  \u003cth\u003eActividad del proyecto\u003c/th\u003e\r\n                  \u003cth\u003eActividad de aprendizaje\u003c/th\u003e\r\n                  \u003cth\u003eEvidencias\u003c/th\u003e\r\n                  \u003cth\u003eCriterios\u003c/th\u003e\r\n                  \u003cth\u003eTecnicas e instrumentos\u003c/th\u003e\r\n                \u003c/tr\u003e\r\n              \u003c/thead\u003e\r\n              \u003ctbody id=\"evidenceTable\"\u003e\u003c/tbody\u003e\r\n            \u003c/table\u003e\r\n          \u003c/div\u003e\r\n        \u003c/div\u003e\r\n      \u003c/div\u003e\r\n\r\n      \u003cdiv id=\"glosario\" class=\"section-title\"\u003eGlosario de T\u0026eacute;rminos\u003c/div\u003e\r\n      \u003cdiv class=\"card open cat-glosario\"\u003e\r\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\r\n          \u003cdiv class=\"card-header-left\"\u003e\r\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128214;\u003c/div\u003e\r\n            \u003cdiv\u003e\r\n              \u003ch3\u003eGlosario de T\u0026eacute;rminos\u003c/h3\u003e\r\n              \u003cp\u003eDefiniciones esenciales para comprender herramientas, instalacion, diagnostico y licenciamiento\u003c/p\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n        \u003c/div\u003e\r\n        \u003cdiv class=\"card-body\"\u003e\r\n          \u003clabel class=\"search-box\"\u003e\r\n            \u003cspan\u003eBuscar termino\u003c/span\u003e\r\n            \u003cinput type=\"search\" id=\"glossarySearch\" placeholder=\"Ejemplo: licenciamiento, checklist, versionado, hardening\"\u003e\r\n          \u003c/label\u003e\r\n          \u003cdiv class=\"glossary-grid\" id=\"glossaryGrid\"\u003e\u003c/div\u003e\r\n        \u003c/div\u003e\r\n      \u003c/div\u003e\r\n\r\n      \u003cdiv id=\"referencias\" class=\"section-title\"\u003eReferentes Bibliogr\u0026aacute;ficos\u003c/div\u003e\r\n      \u003cdiv class=\"card open\"\u003e\r\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\r\n          \u003cdiv class=\"card-header-left\"\u003e\r\n            \u003cdiv class=\"card-icon\" style=\"background:#ede7f6\"\u003e\u0026#128279;\u003c/div\u003e\r\n            \u003cdiv\u003e\r\n              \u003ch3\u003eReferencias Bibliogr\u0026aacute;ficas\u003c/h3\u003e\r\n              \u003cp\u003eFuentes institucionales, tecnicas y webgraficas usadas en la guia\u003c/p\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n        \u003c/div\u003e\r\n        \u003cdiv class=\"card-body\"\u003e\r\n          \u003ch4 style=\"margin:0 0 8px;color:#1b5e20;font-size:0.95rem\"\u003eLibros, documentos institucionales y formaci\u0026oacute;n t\u0026eacute;cnica\u003c/h4\u003e\r\n          \u003col class=\"reference-list\"\u003e\r\n            \u003cli\u003eCisco Networking Academy. (s.\u0026nbsp;f.). \u003cem\u003eIT Support Essentials\u003c/em\u003e. Cisco Systems. \u003ca href=\"https://www.netacad.com/courses/it-support-essentials\" target=\"_blank\" rel=\"noopener noreferrer\"\u003ehttps://www.netacad.com/courses/it-support-essentials\u003c/a\u003e\u003c/li\u003e\r\n            \u003cli\u003eCisco Networking Academy. (s.\u0026nbsp;f.). \u003cem\u003eComputer Hardware Basics\u003c/em\u003e. Cisco Systems. \u003ca href=\"https://www.netacad.com/courses/computer-hardware-basics\" target=\"_blank\" rel=\"noopener noreferrer\"\u003ehttps://www.netacad.com/courses/computer-hardware-basics\u003c/a\u003e\u003c/li\u003e\r\n            \u003cli\u003eServicio Nacional de Aprendizaje SENA. (s.\u0026nbsp;f.). \u003cem\u003eSistema de Bibliotecas SENA\u003c/em\u003e. \u003ca href=\"https://biblioteca.sena.edu.co/\" target=\"_blank\" rel=\"noopener noreferrer\"\u003ehttps://biblioteca.sena.edu.co/\u003c/a\u003e\u003c/li\u003e\r\n          \u003c/ol\u003e\r\n\r\n          \u003ch4 style=\"margin:14px 0 8px;color:#1b5e20;font-size:0.95rem\"\u003eRecursos web y gu\u0026iacute;as t\u0026eacute;cnicas oficiales\u003c/h4\u003e\r\n          \u003col class=\"reference-list\" start=\"4\"\u003e\r\n            \u003cli\u003eThe Document Foundation. (s.\u0026nbsp;f.). \u003cem\u003eLibreOffice Documentation\u003c/em\u003e. \u003ca href=\"https://documentation.libreoffice.org/\" target=\"_blank\" rel=\"noopener noreferrer\"\u003ehttps://documentation.libreoffice.org/\u003c/a\u003e\u003c/li\u003e\r\n            \u003cli\u003e7-Zip. (2026). \u003cem\u003e7-Zip: Download and license information\u003c/em\u003e. \u003ca href=\"https://www.7-zip.org/\" target=\"_blank\" rel=\"noopener noreferrer\"\u003ehttps://www.7-zip.org/\u003c/a\u003e\u003c/li\u003e\r\n            \u003cli\u003eCPUID. (s.\u0026nbsp;f.). \u003cem\u003eCPU-Z: System information software\u003c/em\u003e. \u003ca href=\"https://www.cpuid.com/softwares/cpu-z.html\" target=\"_blank\" rel=\"noopener noreferrer\"\u003ehttps://www.cpuid.com/softwares/cpu-z.html\u003c/a\u003e\u003c/li\u003e\r\n            \u003cli\u003eCrystal Dew World. (s.\u0026nbsp;f.). \u003cem\u003eCrystalDiskInfo: HDD/SSD utility software\u003c/em\u003e. \u003ca href=\"https://crystalmark.info/en/software/crystaldiskinfo/\" target=\"_blank\" rel=\"noopener noreferrer\"\u003ehttps://crystalmark.info/en/software/crystaldiskinfo/\u003c/a\u003e\u003c/li\u003e\r\n            \u003cli\u003eMicrosoft. (2024). \u003cem\u003emsinfo32\u003c/em\u003e. Microsoft Learn. \u003ca href=\"https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/msinfo32\" target=\"_blank\" rel=\"noopener noreferrer\"\u003ehttps://learn.microsoft.com/en-us/windows-server/administration/windows-commands/msinfo32\u003c/a\u003e\u003c/li\u003e\r\n            \u003cli\u003eMicrosoft. (2026). \u003cem\u003eMicrosoft Defender Antivirus in Windows overview\u003c/em\u003e. Microsoft Learn. \u003ca href=\"https://learn.microsoft.com/en-us/defender-endpoint/microsoft-defender-antivirus-windows\" target=\"_blank\" rel=\"noopener noreferrer\"\u003ehttps://learn.microsoft.com/en-us/defender-endpoint/microsoft-defender-antivirus-windows\u003c/a\u003e\u003c/li\u003e\r\n            \u003cli\u003eMicrosoft Support. (s.\u0026nbsp;f.). \u003cem\u003eVirus and threat protection in the Windows Security app\u003c/em\u003e. \u003ca href=\"https://support.microsoft.com/windows/virus-and-threat-protection-in-the-windows-security-app-1362f4cd-d71a-b52a-0b66-c2820032b65e\" target=\"_blank\" rel=\"noopener noreferrer\"\u003ehttps://support.microsoft.com/windows/virus-and-threat-protection-in-the-windows-security-app-1362f4cd-d71a-b52a-0b66-c2820032b65e\u003c/a\u003e\u003c/li\u003e\r\n            \u003cli\u003eIHMC. (s.\u0026nbsp;f.). \u003cem\u003eCmapTools\u003c/em\u003e. Institute for Human and Machine Cognition. \u003ca href=\"https://cmap.ihmc.us/cmaptools/\" target=\"_blank\" rel=\"noopener noreferrer\"\u003ehttps://cmap.ihmc.us/cmaptools/\u003c/a\u003e\u003c/li\u003e\r\n          \u003c/ol\u003e\r\n\r\n          \u003ch4 style=\"margin:14px 0 8px;color:#1b5e20;font-size:0.95rem\"\u003eCiberseguridad, gesti\u0026oacute;n documental y activos de informaci\u0026oacute;n\u003c/h4\u003e\r\n          \u003col class=\"reference-list\" start=\"12\"\u003e\r\n            \u003cli\u003eInstituto Nacional de Ciberseguridad de Espa\u0026ntilde;a INCIBE. (s.\u0026nbsp;f.). \u003cem\u003eBuenas pr\u0026aacute;cticas en el \u0026aacute;rea de inform\u0026aacute;tica\u003c/em\u003e. \u003ca href=\"https://www.incibe.es/empresas/que-te-interesa/buenas-practicas-area-informatica\" target=\"_blank\" rel=\"noopener noreferrer\"\u003ehttps://www.incibe.es/empresas/que-te-interesa/buenas-practicas-area-informatica\u003c/a\u003e\u003c/li\u003e\r\n            \u003cli\u003eMinisterio de Tecnolog\u0026iacute;as de la Informaci\u0026oacute;n y las Comunicaciones MinTIC. (2025). \u003cem\u003eLineamientos para el inventario y clasificaci\u0026oacute;n de activos de informaci\u0026oacute;n e infraestructura cr\u0026iacute;tica cibern\u0026eacute;tica\u003c/em\u003e. \u003ca href=\"https://gobiernodigital.mintic.gov.co/692/articles-401773_recurso_1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\"\u003ehttps://gobiernodigital.mintic.gov.co/692/articles-401773_recurso_1.pdf\u003c/a\u003e\u003c/li\u003e\r\n            \u003cli\u003eMinisterio de Tecnolog\u0026iacute;as de la Informaci\u0026oacute;n y las Comunicaciones MinTIC. (2025). \u003cem\u003eRegistro de activos de informaci\u0026oacute;n\u003c/em\u003e. \u003ca href=\"https://www.mintic.gov.co/portal/715/w3-article-135888.html\" target=\"_blank\" rel=\"noopener noreferrer\"\u003ehttps://www.mintic.gov.co/portal/715/w3-article-135888.html\u003c/a\u003e\u003c/li\u003e\r\n            \u003cli\u003eOrganizaci\u0026oacute;n Internacional de Normalizaci\u0026oacute;n. (2022). \u003cem\u003eISO/IEC 27001:2022 Information security management systems \u0026mdash; Requirements\u003c/em\u003e.\u003c/li\u003e\r\n          \u003c/ol\u003e\r\n        \u003c/div\u003e\r\n      \u003c/div\u003e\r\n\r\n      \u003cdiv id=\"material-apoyo\" class=\"section-title\"\u003eMaterial de Apoyo\u003c/div\u003e\r\n      \u003cdiv class=\"card open\"\u003e\r\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\r\n          \u003cdiv class=\"card-header-left\"\u003e\r\n            \u003cdiv class=\"card-icon\" style=\"background:#e8f0fe\"\u003e\u0026#128194;\u003c/div\u003e\r\n            \u003cdiv\u003e\r\n              \u003ch3\u003eMaterial de Apoyo y Recursos\u003c/h3\u003e\r\n              \u003cp\u003eRecursos oficiales, archivos locales y utilitarios para desarrollar la guia\u003c/p\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n        \u003c/div\u003e\r\n        \u003cdiv class=\"card-body\"\u003e\r\n          \u003cdiv class=\"info-box drive-submit-box\"\u003e\r\n            \u003cdiv class=\"label\"\u003ePortafolio de evidencias \u0026mdash; Carpeta de Drive\u003c/div\u003e\r\n            \u003cp\u003eAccede a la carpeta de Drive de tu grupo para subir tus evidencias y entregas de la Gu\u0026iacute;a 3. La carpeta se determina autom\u0026aacute;ticamente seg\u0026uacute;n tu ficha activa.\u003c/p\u003e\r\n            \u003cdiv class=\"drive-action-group\"\u003e\r\n              \u003cbutton type=\"button\" class=\"btn-drive\" onclick=\"openDriveFolder()\"\u003e\u0026#128193; Abrir carpeta de Drive\u003c/button\u003e\r\n            \u003c/div\u003e\r\n            \u003cdiv class=\"drive-helper-note\"\u003eLa carpeta se define autom\u0026aacute;ticamente seg\u0026uacute;n la ficha activa. Si no tienes sesi\u0026oacute;n iniciada, regresa al portal y selecciona tu grupo.\u003c/div\u003e\r\n          \u003c/div\u003e\r\n\r\n          \u003cdiv class=\"material-heading\"\u003ePaquete general\u003c/div\u003e\r\n          \u003cdiv class=\"resource-grid\" id=\"supportBundleGrid\"\u003e\u003c/div\u003e\r\n\r\n          \u003cdiv class=\"material-heading\"\u003eEnlaces y documentos clave\u003c/div\u003e\r\n          \u003cdiv class=\"resource-grid\" id=\"supportDocsGrid\"\u003e\u003c/div\u003e\r\n\r\n          \u003cdiv class=\"material-heading\"\u003eHerramientas y utilitarios\u003c/div\u003e\r\n          \u003cdiv class=\"resource-grid\" id=\"supportToolsGrid\"\u003e\u003c/div\u003e\r\n\r\n          \u003cdiv class=\"panel-grid\" style=\"margin-top:16px;\"\u003e\r\n            \u003cdiv class=\"support-card\"\u003e\r\n              \u003cimg src=\"assets/img/guia3_portada.png\" alt=\"Portada base de la guia 3\"\u003e\r\n              \u003cp\u003eReferencia visual del documento base usado para construir esta guia interactiva.\u003c/p\u003e\r\n            \u003c/div\u003e\r\n            \u003cdiv class=\"checklist-card\"\u003e\r\n              \u003ch3\u003eMateriales generales sugeridos\u003c/h3\u003e\r\n              \u003cul class=\"note-list\"\u003e\r\n                \u003cli\u003eConsulta primero Cisco NetAcad, Biblioteca SENA y los sitios oficiales de cada herramienta.\u003c/li\u003e\r\n                \u003cli\u003eUtiliza CmapTools para el mapa conceptual y LibreOffice Writer/Calc para las entregas escritas.\u003c/li\u003e\r\n                \u003cli\u003eApoya el diagnostico tecnico con CPU-Z, CrystalDiskInfo y los comandos de red indicados.\u003c/li\u003e\r\n                \u003cli\u003ePara la documentacion tecnica (Act. 3.3.3) usa la plantilla del instructor o LibreOffice Writer con estilos de titulo.\u003c/li\u003e\r\n                \u003cli\u003eOrganiza las evidencias en carpetas con nombres claros siguiendo la convencion aprendida en el Bloque B.\u003c/li\u003e\r\n              \u003c/ul\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n        \u003c/div\u003e\r\n      \u003c/div\u003e\r\n\r\n      \u003cdiv id=\"control-documento\" class=\"section-title\"\u003eControl del Documento\u003c/div\u003e\r\n      \u003cdiv class=\"card open\"\u003e\r\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\r\n          \u003cdiv class=\"card-header-left\"\u003e\r\n            \u003cdiv class=\"card-icon\" style=\"background:#f3e5f5\"\u003e\u0026#128221;\u003c/div\u003e\r\n            \u003cdiv\u003e\r\n              \u003ch3\u003eAutor\u0026iacute;a y Control de Cambios\u003c/h3\u003e\r\n              \u003cp\u003eRegistro oficial de autor\u0026iacute;a, dependencia y modificaciones de la gu\u0026iacute;a\u003c/p\u003e\r\n            \u003c/div\u003e\r\n          \u003c/div\u003e\r\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\r\n        \u003c/div\u003e\r\n        \u003cdiv class=\"card-body\"\u003e\r\n          \u003ch4 style=\"margin:0 0 8px;color:#1b5e20;font-size:0.95rem\"\u003e7. Control del Documento\u003c/h4\u003e\r\n          \u003cdiv class=\"table-scroll\"\u003e\r\n            \u003ctable class=\"data-table\"\u003e\r\n              \u003cthead\u003e\r\n                \u003ctr\u003e\r\n                  \u003cth\u003eNombre\u003c/th\u003e\r\n                  \u003cth\u003eCargo\u003c/th\u003e\r\n                  \u003cth\u003eDependencia\u003c/th\u003e\r\n                  \u003cth\u003eFecha\u003c/th\u003e\r\n                \u003c/tr\u003e\r\n              \u003c/thead\u003e\r\n              \u003ctbody\u003e\r\n                \u003ctr\u003e\r\n                  \u003ctd\u003ePeter Emerson Pinchao\u003c/td\u003e\r\n                  \u003ctd\u003eExperto Tem\u0026aacute;tico\u003c/td\u003e\r\n                  \u003ctd\u003eCTPI\u003c/td\u003e\r\n                  \u003ctd\u003e2/11/2022\u003c/td\u003e\r\n                \u003c/tr\u003e\r\n              \u003c/tbody\u003e\r\n            \u003c/table\u003e\r\n          \u003c/div\u003e\r\n\r\n          \u003ch4 style=\"margin:18px 0 8px;color:#1b5e20;font-size:0.95rem\"\u003e8. Control de Cambios\u003c/h4\u003e\r\n          \u003cp style=\"font-size:0.85rem;color:#666;margin:0 0 8px\"\u003e(Diligenciar \u0026uacute;nicamente si se realizan ajustes a la gu\u0026iacute;a)\u003c/p\u003e\r\n          \u003cdiv class=\"table-scroll\"\u003e\r\n            \u003ctable class=\"data-table\"\u003e\r\n              \u003cthead\u003e\r\n                \u003ctr\u003e\r\n                  \u003cth\u003eNombre\u003c/th\u003e\r\n                  \u003cth\u003eCargo\u003c/th\u003e\r\n                  \u003cth\u003eDependencia\u003c/th\u003e\r\n                  \u003cth\u003eFecha\u003c/th\u003e\r\n                  \u003cth\u003eRaz\u0026oacute;n del cambio\u003c/th\u003e\r\n                \u003c/tr\u003e\r\n              \u003c/thead\u003e\r\n              \u003ctbody\u003e\r\n                \u003ctr\u003e\r\n                  \u003ctd\u003ePeter Emerson Pinchao\u003c/td\u003e\r\n                  \u003ctd\u003eExperto Tem\u0026aacute;tico\u003c/td\u003e\r\n                  \u003ctd\u003eCTPI\u003c/td\u003e\r\n                  \u003ctd\u003e2/11/2022\u003c/td\u003e\r\n                  \u003ctd\u003e\u0026mdash;\u003c/td\u003e\r\n                \u003c/tr\u003e\r\n                \u003ctr\u003e\r\n                  \u003ctd\u003eGilberto Gonz\u0026aacute;lez Medina\u003c/td\u003e\r\n                  \u003ctd\u003eExperto t\u0026eacute;cnico\u003c/td\u003e\r\n                  \u003ctd\u003eCTPI Cauca\u003c/td\u003e\r\n                  \u003ctd\u003e14/06/2023\u003c/td\u003e\r\n                  \u003ctd\u003eActualizaci\u0026oacute;n\u003c/td\u003e\r\n                \u003c/tr\u003e\r\n                \u003ctr\u003e\r\n                  \u003ctd\u003eDubier Orlando Mill\u0026aacute;n Barbosa\u003c/td\u003e\r\n                  \u003ctd\u003eInstructor T\u0026eacute;cnico\u003c/td\u003e\r\n                  \u003ctd\u003eCIAS \u0026mdash; Regional Boyac\u0026aacute;\u003c/td\u003e\r\n                  \u003ctd\u003eMay. 2025\u003c/td\u003e\r\n                  \u003ctd\u003eAjuste a RAP 02.\u003c/td\u003e\r\n                \u003c/tr\u003e\r\n              \u003c/tbody\u003e\r\n            \u003c/table\u003e\r\n          \u003c/div\u003e\r\n        \u003c/div\u003e\r\n      \u003c/div\u003e\r\n    \u003c/div\u003e\r\n  \u003c/div\u003e\r\n\u003c/div\u003e\r\n\u003cdiv class=\"modal-overlay\" id=\"bitacora-export-modal\" onclick=\"if(event.target===this)closeBitacoraExportModal()\"\u003e\r\n  \u003cdiv class=\"modal-box\"\u003e\r\n    \u003ch3\u003e\u0026#128196; Exportar bitacora de analisis\u003c/h3\u003e\r\n    \u003cp\u003eIngresa tu \u003cstrong\u003enombre completo\u003c/strong\u003e para descargar esta actividad en formato Word.\u003c/p\u003e\r\n\r\n    \u003cdiv class=\"modal-ficha-warn\" id=\"bitacora-modal-warn\" style=\"display:none\"\u003e\r\n      \u0026#9888; \u003cstrong\u003eNo has seleccionado tu ficha.\u003c/strong\u003e\u003cbr\u003e\r\n      Regresa a \u003ca href=\"index.html\"\u003ela pagina de inicio\u003c/a\u003e y elige tu institucion y grupo antes de exportar.\r\n    \u003c/div\u003e\r\n\r\n    \u003cdiv class=\"modal-ficha-ok\" id=\"bitacora-modal-ok\" style=\"display:none\"\u003e\r\n      \u003cdiv class=\"mf-label\"\u003eNombre sugerido del archivo\u003c/div\u003e\r\n      \u003cdiv class=\"mf-file\" id=\"bitacora-filename-preview\"\u003eBitacora_Analisis_Nombre.doc\u003c/div\u003e\r\n    \u003c/div\u003e\r\n\r\n    \u003cinput\r\n      type=\"text\"\r\n      id=\"bitacora-nombre\"\r\n      placeholder=\"Nombre y apellidos del aprendiz\"\r\n      maxlength=\"80\"\r\n      oninput=\"updateBitacoraFilenamePreview()\"\r\n      onkeydown=\"if(event.key==='Enter')doExportBitacoraWord()\"\r\n    \u003e\r\n    \u003cdiv class=\"modal-error-msg\" id=\"bitacora-modal-error\"\u003ePor favor ingresa tu nombre antes de continuar.\u003c/div\u003e\r\n\r\n    \u003cdiv class=\"modal-actions\"\u003e\r\n      \u003cbutton class=\"modal-btn-cancel\" type=\"button\" onclick=\"closeBitacoraExportModal()\"\u003eCancelar\u003c/button\u003e\r\n      \u003cbutton class=\"modal-btn-ok\" id=\"bitacora-modal-btn\" type=\"button\" onclick=\"doExportBitacoraWord()\"\u003eDescargar Word\u003c/button\u003e\r\n    \u003c/div\u003e\r\n  \u003c/div\u003e\r\n\u003c/div\u003e\r\n\r\n\u003cscript\u003e\r\n(function () {\r\n  function buildGuideRouteHref(fileName) {\r\n    return \"guia.html?g=\" + encodeURIComponent(fileName);\r\n  }\r\n\r\n  var grupo = String((document.body \u0026\u0026 document.body.dataset \u0026\u0026 document.body.dataset.defaultGrupo) || \"10A\").toUpperCase();\r\n  var config = {\r\n    \"10A\": {\r\n      currentFile: \"grupo-10a-guia-03-planificar-informacion.html\",\r\n      currentLabel: \"Implementar componentes | 10A\",\r\n      campus: \"Jhon F. Kennedy | 10A\"\r\n    },\r\n    \"10B\": {\r\n      currentFile: \"grupo-10b-guia-03-planificar-informacion.html\",\r\n      currentLabel: \"Implementar componentes | 10B\",\r\n      campus: \"Jhon F. Kennedy | 10B\"\r\n    }\r\n  }[grupo] || null;\r\n\r\n  if (!config) {\r\n    return;\r\n  }\r\n\r\n  var currentGuideNavLink = document.getElementById(\"currentGuideNavLink\");\r\n  var currentGuideNavLabel = document.getElementById(\"currentGuideNavLabel\");\r\n  var topbarCampus = document.getElementById(\"topbarCampus\");\r\n\r\n  if (currentGuideNavLink) {\r\n    currentGuideNavLink.href = buildGuideRouteHref(config.currentFile);\r\n    currentGuideNavLink.dataset.currentFile = config.currentFile;\r\n  }\r\n  if (currentGuideNavLabel) {\r\n    currentGuideNavLabel.textContent = config.currentLabel;\r\n  }\r\n  if (topbarCampus) {\r\n    topbarCampus.textContent = config.campus;\r\n  }\r\n})();\r\n\u003c/script\u003e\r\n\r\n";
